def name_key(name):
    """A name as it is typed after @: lower case, a doubled letter as one ("Aanya" and "Anya" alike)."""
    return re.sub(r"(.)\1+", r"\1", str(name).lower())


def name_sound(name):
    """A name as it sounds: y as i, ph as f, an h after the first letter silent ("Riya" and "Rhea" alike)."""
    text = str(name).lower().replace("y", "i").replace("ph", "f")
    return name_key(text[:1] + text[1:].replace("h", ""))


def _one_letter_apart(a, b):
    """The same, or one letter added, dropped or changed apart."""
    if a == b:
        return True
    if abs(len(a) - len(b)) > 1:
        return False
    if len(a) > len(b):
        a, b = b, a
    i = 0
    while i < len(a) and a[i] == b[i]:
        i += 1
    # One change (same length), or one letter more in b (b one longer): the rest must match.
    return a[i + 1:] == b[i + 1:] if len(a) == len(b) else a[i:] == b[i + 1:]


def names_look_alike(one, two):
    """Whether two names are close enough to be mixed up in an @mention or --to: one letter apart once case and
    doubled letters are ignored ("Aanya" and "Anya", "Zara" and "Yara"), or as they sound ("Riya" and "Rhea"), or
    the same first two letters and the same last one ("Anya" and "Anika")."""
    a, b = name_key(one), name_key(two)
    if _one_letter_apart(a, b) or _one_letter_apart(name_sound(one), name_sound(two)):
        return True
    return len(a) > 2 and len(b) > 2 and a[:2] == b[:2] and a[-1] == b[-1]


