def home():
    return Path(os.environ.get("CREWCHAT_HOME", "~/.crewchat")).expanduser()


def now_iso(ts=None):
    return time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime(ts if ts is not None else time.time()))


def sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


TAGLINE = "one group chat for all your AI agents"


def banner(stream=None):
    """The logo, a speech bubble holding three connected agents, with the name and version: in
    colour on a terminal that can show it, else the plain name and version."""
    stream = stream or sys.stdout
    plain = "crewchat %s" % __version__
    try:
        if not stream.isatty() or os.environ.get("TERM") == "dumb":
            return plain
        "\u256d\u25cf\u2571".encode(stream.encoding or "ascii")
    except (AttributeError, ValueError, UnicodeError, LookupError):
        return plain
    colour = not os.environ.get("NO_COLOR") and (os.name != "nt" or windows_vt())
    b, w, d, r = ("\033[38;5;69m", "\033[1;97m", "\033[38;5;250m", "\033[0m") if colour else ("",) * 4
    return "\n".join([
        "%s\u256d\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u256e%s" % (b, r),
        "%s\u2502%s     %s\u25cf%s     %s\u2502%s   %screwchat%s %s" % (b, r, w, r, b, r, w, r, __version__),
        "%s\u2502%s    %s\u2571 \u2572%s    %s\u2502%s   %s" % (b, r, d, r, b, r, TAGLINE),
        "%s\u2502%s   %s\u25cf%s\u2500\u2500\u2500%s\u25cf%s   %s\u2502%s" % (b, r, w, d, w, r, b, r),
        "%s\u2570\u2500\u2500\u256e \u256d\u2500\u2500\u2500\u2500\u2500\u2500\u256f%s" % (b, r),
        "%s   \u2502\u2571%s" % (b, r),
    ])


def windows_vt():
    """Switch this Windows console to understanding colour codes. True if it does."""
    try:
        import ctypes
        kernel = ctypes.windll.kernel32
        handle = kernel.GetStdHandle(-11)
        mode = ctypes.c_uint32()
        return bool(kernel.GetConsoleMode(handle, ctypes.byref(mode))
                    and kernel.SetConsoleMode(handle, mode.value | 0x0004))
    except Exception:
        return False


def die(message):
    sys.exit("crewchat: %s" % message)


class HubError(Exception):
    pass


# --------------------------------------------------------------------------------------------
# QR codes, for the phone panel: the sign-in link as a code a phone's camera opens (standard library only).
# Byte mode, error correction level L, versions 1 to 6 (up to 134 bytes): enough for a tailnet address with a
# sign-in code. ISO/IEC 18004; the mask with the lowest penalty is used, as a reader expects nothing else.
# --------------------------------------------------------------------------------------------
QR_BLOCKS = {1: (1, 19, 7), 2: (1, 34, 10), 3: (1, 55, 15), 4: (1, 80, 20), 5: (1, 108, 26), 6: (2, 68, 18)}
QR_ALIGN = {2: 18, 3: 22, 4: 26, 5: 30, 6: 34}  # the one alignment pattern's centre, versions 2 to 6


def _qr_gf():
    exp, log, x = [0] * 512, [0] * 256, 1
    for i in range(255):
        exp[i], log[x] = x, i
        x <<= 1
        if x & 0x100:
            x ^= 0x11D
    for i in range(255, 512):
        exp[i] = exp[i - 255]
    return exp, log


QR_EXP, QR_LOG = _qr_gf()


def _qr_ec(data, n):
    """Reed-Solomon: the n error correction bytes of data."""
    gen = [1]
    for i in range(n):
        nxt = [0] * (len(gen) + 1)
        for j, g in enumerate(gen):
            nxt[j] ^= g
            if g:
                nxt[j + 1] ^= QR_EXP[QR_LOG[g] + i]
        gen = nxt
    rem = list(data) + [0] * n
    for i in range(len(data)):
        c = rem[i]
        if c:
            for j in range(1, len(gen)):
                if gen[j]:
                    rem[i + j] ^= QR_EXP[QR_LOG[gen[j]] + QR_LOG[c]]
    return rem[len(data):]


def _qr_bits(value, length):
    return [(value >> (length - 1 - i)) & 1 for i in range(length)]


def qr_matrix(text):
    """TEXT as a QR code: a list of rows, each a string of '1' (dark) and '0', without the quiet zone.
    ValueError when it does not fit in version 6."""
    data = text.encode("utf-8")
    version = next((v for v, (blocks, size, _) in sorted(QR_BLOCKS.items())
                    if 4 + 8 + 8 * len(data) <= blocks * size * 8), None)
    if version is None:
        raise ValueError("too long for a QR code here: %d bytes (at most 134)" % len(data))
    blocks, size, ecn = QR_BLOCKS[version]
    capacity = blocks * size * 8
    bits = _qr_bits(4, 4) + _qr_bits(len(data), 8)
    for b in data:
        bits += _qr_bits(b, 8)
    bits += [0] * min(4, capacity - len(bits))
    bits += [0] * (-len(bits) % 8)
    words = [int("".join(map(str, bits[i:i + 8])), 2) for i in range(0, len(bits), 8)]
    pad = 0
    while len(words) < blocks * size:
        words.append((0xEC, 0x11)[pad % 2])
        pad += 1
    parts = [words[i * size:(i + 1) * size] for i in range(blocks)]
    ecs = [_qr_ec(p, ecn) for p in parts]
    stream = [p[i] for i in range(size) for p in parts] + [e[i] for i in range(ecn) for e in ecs]

    n = 17 + 4 * version
    grid = [[None] * n for _ in range(n)]

    def put(r, c, dark):
        if 0 <= r < n and 0 <= c < n:
            grid[r][c] = 1 if dark else 0

    for r0, c0 in ((0, 0), (0, n - 7), (n - 7, 0)):  # finders, with their white edge
        for r in range(-1, 8):
            for c in range(-1, 8):
                ring = max(abs(r - 3), abs(c - 3))
                put(r0 + r, c0 + c, ring != 2 and ring != 4)
    if version in QR_ALIGN:
        a = QR_ALIGN[version]
        for r in range(-2, 3):
            for c in range(-2, 3):
                put(a + r, a + c, max(abs(r), abs(c)) != 1)
    for i in range(8, n - 8):  # timing
        put(6, i, i % 2 == 0)
        put(i, 6, i % 2 == 0)
    put(n - 8, 8, True)  # the dark module
    reserved = [(8, i) for i in range(9)] + [(i, 8) for i in range(8)] + \
        [(8, n - 1 - i) for i in range(8)] + [(n - 1 - i, 8) for i in range(7)]
    for r, c in reserved:
        if grid[r][c] is None:
            grid[r][c] = 0
    fixed = [[cell is not None for cell in row] for row in grid]

    stream_bits = []
    for w in stream:
        stream_bits += _qr_bits(w, 8)
    k, col, upward = 0, n - 1, True
    while col > 0:
        if col == 6:
            col -= 1
        for i in range(n):
            r = n - 1 - i if upward else i
            for c in (col, col - 1):
                if not fixed[r][c]:
                    grid[r][c] = stream_bits[k] if k < len(stream_bits) else 0
                    k += 1
        upward = not upward
        col -= 2

    masks = (lambda r, c: (r + c) % 2 == 0, lambda r, c: r % 2 == 0, lambda r, c: c % 3 == 0,
             lambda r, c: (r + c) % 3 == 0, lambda r, c: (r // 2 + c // 3) % 2 == 0,
             lambda r, c: (r * c) % 2 + (r * c) % 3 == 0, lambda r, c: ((r * c) % 2 + (r * c) % 3) % 2 == 0,
             lambda r, c: ((r + c) % 2 + (r * c) % 3) % 2 == 0)

    def format_bits(mask):
        value = (1 << 3) | mask  # level L is 01
        rem = value << 10
        for i in range(14, 9, -1):
            if rem >> i & 1:
                rem ^= 0x537 << (i - 10)
        return ((value << 10) | rem) ^ 0x5412

    def masked(mask):
        g = [[grid[r][c] ^ (1 if not fixed[r][c] and masks[mask](r, c) else 0) for c in range(n)] for r in range(n)]
        f = format_bits(mask)
        for i in range(15):
            bit = f >> i & 1
            if i < 6:  # the copy round the top-left finder
                g[i][8] = bit
            elif i < 8:
                g[i + 1][8] = bit
            elif i == 8:
                g[8][7] = bit
            else:
                g[8][14 - i] = bit
            if i < 8:  # and the copy split between the other two
                g[8][n - 1 - i] = bit
            else:
                g[n - 15 + i][8] = bit
        g[n - 8][8] = 1
        return g

    def penalty(g):
        score = 0
        lines = g + [list(col) for col in zip(*g)]
        for line in lines:
            run = 1
            for i in range(1, n + 1):
                if i < n and line[i] == line[i - 1]:
                    run += 1
                else:
                    if run >= 5:
                        score += run - 2
                    run = 1
            s = "".join(map(str, line))
            score += 40 * (s.count("10111010000") + s.count("00001011101"))
        for r in range(n - 1):
            for c in range(n - 1):
                if g[r][c] == g[r + 1][c] == g[r][c + 1] == g[r + 1][c + 1]:
                    score += 3
        dark = sum(map(sum, g)) * 100 // (n * n)
        return score + abs(dark - 50) // 5 * 10

    best = min((masked(m) for m in range(8)), key=penalty)
    return ["".join(map(str, row)) for row in best]
# --------------------------------------------------------------------------------------------
# Names, places and configuration
# --------------------------------------------------------------------------------------------
def check_name(name):
    if not isinstance(name, str) or not NAME_RE.match(name):
        raise HubError("names start with a letter and use letters, digits, - _ . (32 at most): %r" % (name,))
    if name.lower() in (OWNER.lower(), "all", SERVER_NAME):
        raise HubError("%r is reserved" % name)
    return name


def slug(text, limit, fallback):
    word = re.sub(r"[^a-z0-9]+", "-", str(text).lower()).strip("-")[:limit].strip("-")
    return word if word and word[0].isalpha() else fallback


def client_kind(info):
    """A short word for the agent's tool, from the MCP clientInfo it sent ("claude", "cursor", ...)."""
    name = str(info.get("name", "") if isinstance(info, dict) else "").lower()
    for known in KNOWN_CLIENTS:
        if known in name:
            return known
    return slug(name, 12, "agent")


def place_label(text):
    """A short word for a machine or folder, used in agent names ("macbook"). A long name is cut
    at a word break: "Deepankars-Mac-mini" is "deepankars-mac", not "deepankars-mac-m"."""
    word = slug(str(text).split(".")[0], 64, "machine")
    if len(word) > 16:
        cut = word[:17].rfind("-")
        word = word[:cut] if cut >= 3 else word[:16].strip("-")
    return word


def machine_name():
    """This machine's short name, from its host name ("machine" if it has none to give)."""
    try:
        host = socket.gethostname()
    except OSError:
        host = "machine"
    return place_label(host.split(".")[0])


def load_config(root=None):
    root = root or home()
    path = root / "config.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except OSError:
        die("not set up here yet; run `crewchat setup` first (looked in %s)" % root)
    except ValueError:
        die("%s is not valid JSON" % path)
    data.setdefault("project", "this project")
    data.setdefault("port", DEFAULT_PORT)
    data.setdefault("url", "")
    data.setdefault("forget_hours", FORGET_HOURS)
    return data


def clean_label(value):
    return " ".join(str(value or "").split())[:MAX_ROLE_LABEL]


def clean_role(spec):
    """A role as crewchat keeps it, {label, description, picture, colour, tool}, from config.json, a
    pack or an import (title and prompt are read too, as before 0.14). None if it has no instructions."""
    if not isinstance(spec, dict):
        return None
    description = str(spec.get("description") or spec.get("prompt") or "").strip()
    if not description:
        return None
    tool = str(spec.get("tool") or "")
    return {"label": clean_label(spec.get("label") or spec.get("title")),
            "description": description[:MAX_ROLE_TEXT], "picture": clean_picture(spec.get("picture")),
            "colour": clean_colour(spec.get("colour")), "tool": tool if tool in TOOLS_INFO else "",
            "powers": clean_powers(spec.get("powers")), "reports_to": clean_reports_to(spec.get("reports_to"))}


def clean_powers(value):
    """A role's powers, in POWERS' order; None when it has none saved (its name then decides, DEFAULT_POWERS).
    A string is read as a comma-separated list."""
    if value is None:
        return None
    if isinstance(value, str):
        value = value.split(",")
    if not isinstance(value, (list, tuple)):
        return None
    words = {str(w).strip().lower() for w in value}
    return [p for p in POWERS if p in words]


def clean_reports_to(value):
    """The role a role reports to (H2), or "": the project's top lead, or else the owner."""
    name = str(value or "").strip().lower()
    return name if NAME_RE.match(name) else ""


def clean_pack(spec):
    """An owner's saved pack, {label, crew, roles}, or None if it is not one."""
    if not isinstance(spec, dict) or not isinstance(spec.get("roles"), dict):
        return None
    roles = {str(n).lower(): clean_role(r) for n, r in spec["roles"].items() if NAME_RE.match(str(n))}
    return {"label": clean_label(spec.get("label")) or "My pack",
            "crew": spec.get("crew") if spec.get("crew") in CREWS else "general",
            "roles": {n: r for n, r in roles.items() if r}}


def role_packs(base=None):
    """The packs a project can start from, by id: the built-in ones, then the owner's saved ones
    (the machine's config.json, "packs")."""
    out = dict(ROLE_PACKS)
    path = (Path(base) if base else home()) / "config.json"
    try:
        saved = json.loads(path.read_text(encoding="utf-8")).get("packs")
    except (OSError, ValueError, AttributeError):
        saved = None
    for pid, spec in (saved.items() if isinstance(saved, dict) else ()):
        pack = clean_pack(spec)
        if pack and NAME_RE.match(str(pid)) and pid not in ROLE_PACKS:
            out[str(pid)] = dict(pack, saved=True)
    return out


def project_pack(config, packs):
    """The id of the pack a project's roles start from ("software" before 0.14, or if it is gone)."""
    pack = str(config.get("pack") or DEFAULT_PACK)
    return pack if pack in packs else DEFAULT_PACK


def role_table(config, packs):
    """A project's roles, {name: {label, description, picture, colour, tool, source}}: its pack's,
    then the owner's own from config.json ("roles": {name: role}). An owner's role with a pack
    role's name replaces it, and {"deleted": true} takes one of the pack's away."""
    out = {}
    for name, spec in packs[project_pack(config, packs)]["roles"].items():
        row = clean_role(spec)
        if row:
            out[name] = dict(row, source="pack")
    custom = config.get("roles") if isinstance(config.get("roles"), dict) else {}
    for name, spec in custom.items():
        name = str(name).lower()  # every op lowercases a role's name
        if not NAME_RE.match(name):
            continue
        if isinstance(spec, dict) and spec.get("deleted"):
            out.pop(name, None)
            continue
        row = clean_role(spec)
        if row:
            out[name] = dict(row, source="yours")
    for name, row in out.items():
        row["label"] = row["label"] or name.replace("-", " ").replace("_", " ").capitalize()
        if row["powers"] is None:
            row["powers"] = clean_powers(DEFAULT_POWERS.get(name, ()))
        if row["reports_to"] not in out or row["reports_to"] == name:
            row["reports_to"] = ""  # (a role it named is gone)
    for name, row in out.items():  # a loop, from a config.json edited by hand, is cut where it closes
        seen = [name]
        while out[seen[-1]]["reports_to"]:
            up = out[seen[-1]]["reports_to"]
            if up in seen:
                out[seen[-1]]["reports_to"] = ""
                break
            seen.append(up)
    return out


def top_role(table):
    """The role at the top of a project's tree: the one with the assign power that reports to no role, or ""."""
    return next((n for n, r in table.items() if "assign" in r["powers"] and not r["reports_to"]), "")


def role_chain(table, role):
    """The roles above a role, nearest first, ending at the top role when the chain does not reach it itself (a
    role that reports to no role works under the top lead)."""
    out, seen = [], {role}
    row = table.get(role)
    while row and row["reports_to"] and row["reports_to"] not in seen:
        out.append(row["reports_to"])
        seen.add(row["reports_to"])
        row = table.get(row["reports_to"])
    top = top_role(table)
    if top and top not in seen:
        out.append(top)
    return out


def check_role_tree(table, changed):
    """Refuse a change to roles that leaves a role reporting to one that does not exist, a loop, or two roles at
    the top with the assign power (one top lead, H0). changed: the roles the change wrote."""
    for name in changed:
        row = table.get(name)
        if not row:
            continue
        up = row["reports_to"]
        if up and up not in table:
            raise HubError("%s cannot report to %s: there is no role called %s" % (name, up, up))
        seen = [name]
        while up:
            if up in seen:
                raise HubError("%s cannot report to %s: that makes a loop (%s)" % (
                    name, row["reports_to"], " > ".join(seen + [up])))
            seen.append(up)
            up = (table.get(up) or {}).get("reports_to", "")
    tops = [n for n, r in table.items() if "assign" in r["powers"] and not r["reports_to"]]
    if len(tops) > 1:
        raise HubError("a project has one top lead, and %s both hand out work and report to no role: give one of "
                       "them reports_to (the role it works under), or take its assign power" % " and ".join(tops))


def tree_of(table):
    """A project's tree as it travels between machines (H4): {role: {"powers": [...], "reports_to": role}}."""
    return {n: {"powers": list(r["powers"]), "reports_to": r["reports_to"]} for n, r in table.items()}


def clean_tree(value):
    """A tree from a message (JSON text), cleaned; {} if it is not one."""
    try:
        data = json.loads(value) if isinstance(value, str) else value
    except ValueError:
        return {}
    if not isinstance(data, dict):
        return {}
    out = {}
    for name, row in list(data.items())[:MAX_IMPORT_ROLES * 2]:
        name = str(name).lower()
        if NAME_RE.match(name) and isinstance(row, dict):
            out[name] = {"powers": clean_powers(row.get("powers")) or [],
                         "reports_to": clean_reports_to(row.get("reports_to"))}
    return out


def apply_shared_tree(root, tree):
    """Take a tree another machine shared (H4) into this project's config.json: each role this machine has gets the
    tree's powers and reports_to. Roles it does not have are left out. Returns whether config.json changed."""
    with ROLES_LOCK, CONFIG_LOCK:
        config = load_config(root)
        table = role_table(config, role_packs())
        if not isinstance(config.get("roles"), dict):
            config["roles"] = {}
        changed = False
        for name, row in tree.items():
            mine = table.get(name)
            up = row["reports_to"] if row["reports_to"] in table and row["reports_to"] != name else ""
            if not mine or (mine["powers"], mine["reports_to"]) == (row["powers"], up):
                continue
            config["roles"][name] = clean_role(dict(mine, powers=row["powers"], reports_to=up))
            changed = True
        if changed:
            save_config(config, root)
        return changed


def role_tree_lines(table):
    """A project's roles as an indented tree, for `crewchat roles tree` and the role text."""
    below = {}
    for name, row in table.items():
        below.setdefault(row["reports_to"], []).append(name)
    top = top_role(table)
    lines = []

    def walk(name, depth):
        row = table[name]
        powers = ", ".join(row["powers"])
        lines.append("%s%s (%s)%s" % ("  " * depth, row["label"], name, " [%s]" % powers if powers else ""))
        for child in below.get(name, ()):
            walk(child, depth + 1)
    roots = below.get("", [])
    if top:
        walk(top, 0)
        for name in roots:
            if name != top:
                walk(name, 1)
    else:
        for name in roots:
            walk(name, 0)
    return lines


def role_texts(table):
    """Roles as {name: (label, description)}: what an agent is told when it gets one."""
    return {name: (row["label"], row["description"]) for name, row in table.items()}


ROLE_FIELDS = ("label", "description", "picture", "colour", "tool", "powers", "reports_to")
MAX_IMPORT_ROLES = 50
NEEDS_LOOKBACK = 2000  # messages scanned for an agent's newest word on a task
NEEDS_MESSAGES = 20  # unread messages that ask the owner something, shown in Needs you
def reply_to(text):
    """The task an owner's "Re #12: ..." answers, or "" (how Needs you knew a reply before the `re` field, R8)."""
    found = re.match(r"Re #([A-Za-z]*\d+): ", text or "")
    return found.group(1) if found else ""


# Every kind of item in Needs you (R8), the one list of them: its place in the list, how the page and a push name
# it, its colour on the page, and how the owner answers it (buttons, a reply, or opening what it points at).
NEED_KINDS = {"permission": (-1, "Asks permission", "--err", "buttons"), "question": (-1, "Question", "--err", "buttons"),
              "browser": (-1, "Browser", "--err", "buttons"),
              "device": (-1, "Mobile device", "--err", "buttons"),
              "gchat": (-1, "Google Chat post", "--err", "buttons"),
              "jira_flow": (0, "Jira ticket", "--warn", "buttons"),
              "firstrun": (-1, "First run", "--err", "buttons"), "stuck": (-1, "Stuck", "--err", "buttons"),
              "start_failed": (-1, "Not started", "--err", "buttons"),
              "ended": (1, "Session ended", "--warn", "buttons"),
              "blocked": (0, "Needs you", "--err", "reply"),
              "parked": (0, "Parked", "--warn", "reply"), "review": (1, "In review", "--warn", "reply"),
              "process": (2, "Process note", "--accent", "buttons"), "message": (2, "Question for you", "--accent", "open"),
              "reclaimed": (3, "Reclaimed", "--off", "open"), "given_back": (3, "Given back", "--off", "open"),
              "ask": (1, "Unanswered", "--warn", "buttons"), "lease": (0, "Commit stopped", "--err", "buttons")}
# The answers of a Needs you item that has buttons; a permission prompt's, the browser's and a mobile device's depend
# on what was asked.
NEED_CHOICES = {"process": ["approve", "decline"], "gchat": ["post", "drop"], "firstrun": ["approve", "cancel"],
                "start_failed": ["retry", "dismiss"], "stuck": ["show", "attach", "stop"], "ask": ["nudge", "reply"],
                "lease": ["ask", "release"], "ended": ["reopen", "dismiss"]}
# Needs you items only the machine that has them knows (asks held in its memory, its background agents, its commits):
# they show on every linked machine's page too, and an answer there goes back to this machine (crewchat's own link,
# /peer/needs). The rest (blocked tasks, reviews, messages, process notes, Jira) come from the chat every machine has.
SHARED_NEED_KINDS = ("permission", "question", "browser", "device", "gchat", "firstrun", "stuck", "start_failed",
                     "lease")
# Answers only this machine's own page gives: Show terminal and Open in Terminal act on a window here.
HOST_ONLY_ANSWERS = {"stuck": ("show", "attach")}
MAX_REMOTE_NEEDS = 50  # a linked machine's items kept, at most


def permission_choices(plan, rule):
    """A permission prompt's answers: a plan's (W3), another tool's call that may be always allowed (W5), or else
    Allow and Deny."""
    return ["allow_edits", "allow", "deny"] if plan else ["allow", "allow_always", "deny"] if rule else ["allow", "deny"]
MAX_PROJECT_NAME = 60
ROLES_LOCK = threading.Lock()  # one change to a config.json's roles at a time


def role_name(value):
    return check_name(str(value or "").strip().lower())


def find_pack(pid, packs):
    if pid not in packs:
        raise HubError("no pack called %s. Packs: %s" % (pid, ", ".join(packs)))
    return packs[pid]


def roles_export(table, names=None):
    """Roles as a file the owner can keep or import into another project."""
    return {"crewchat": "roles", "version": 1, "roles": {
        name: {k: row[k] for k in ROLE_FIELDS} for name, row in table.items() if names is None or name in names}}


def roles_listing(config, packs, table):
    """What the page needs to show and edit a project's roles."""
    return {"pack": project_pack(config, packs), "roles": [dict(row, name=name) for name, row in table.items()],
            "packs": [{"id": pid, "label": p["label"], "crew": p["crew"], "roles": list(p["roles"]),
                       "saved": bool(p.get("saved"))} for pid, p in packs.items()]}


def save_roles_change(root, data):
    """change_roles on a project's config.json, saved (a new pack in the machine's config.json)."""
    with ROLES_LOCK, CONFIG_LOCK:  # (CONFIG_LOCK: other settings saved meanwhile are not lost)
        config = load_config(root)
        answer, effects = change_roles(config, data, role_packs())
        if "saved_pack" in effects:
            mine = load_config()
            if not isinstance(mine.get("packs"), dict):
                mine["packs"] = {}
            mine["packs"][effects["saved_pack"][0]] = effects["saved_pack"][1]
            save_config(mine)
        elif effects.get("changed"):
            save_config(config, root)
    return answer, effects


def _import_rows(spec):
    """The roles in an import, all checked before any is kept."""
    if isinstance(spec, dict) and isinstance(spec.get("roles"), (dict, list)):
        spec = spec["roles"]  # a whole exported file
    if isinstance(spec, list):
        if not all(isinstance(r, dict) for r in spec):
            raise HubError("roles to import are a list of roles, each with a name")
        spec = {r.get("name"): r for r in spec}
    if not isinstance(spec, dict) or not spec:
        raise HubError("nothing to import: give roles as exported by crewchat")
    if len(spec) > MAX_IMPORT_ROLES:
        raise HubError("import at most %d roles at once" % MAX_IMPORT_ROLES)
    rows = {}
    for raw, role in spec.items():
        name = role_name(raw)
        rows[name] = clean_role(role)
        if rows[name] is None:
            raise HubError("the role %s has no description" % name)
    return rows


def change_roles(config, data, packs):
    """One change the owner makes to a project's roles (data["op"]), applied to config in place; the
    caller saves it. Returns (answer, effects): effects["changed"] when config changed, and
    effects["saved_pack"], (id, pack), for the machine's packs."""
    op = str(data.get("op") or "list")
    table = role_table(config, packs)
    if op == "list":
        return roles_listing(config, packs, table), {}
    if op == "export":
        names = data.get("names")
        return roles_export(table, set(map(str, names)) if isinstance(names, list) else None), {}
    if op == "save_pack":  # this project's roles, as a pack other projects can start from
        pid = role_name(data.get("id") or slug(str(data.get("label") or ""), 32, "pack"))
        if pid in ROLE_PACKS:
            raise HubError("%s is a built-in pack; choose another name" % pid)
        if packs.get(pid, {}).get("saved") and not data.get("replace"):
            raise HubError("there is a pack called %s already; replace it, or choose another name" % pid)
        crew = data.get("crew") if data.get("crew") in CREWS else packs[project_pack(config, packs)]["crew"]
        pack = clean_pack({"label": data.get("label") or pid, "crew": crew, "roles": roles_export(table)["roles"]})
        return {"pack": dict(pack, id=pid)}, {"saved_pack": (pid, pack)}
    if not isinstance(config.get("roles"), dict):
        config["roles"] = {}
    custom = config["roles"]

    def existing():
        name = role_name(data.get("name"))
        if name not in table:
            raise HubError("no role called %s" % name)
        return name

    def keep(name, spec):
        for field, ok in (("picture", clean_picture), ("colour", clean_colour)):
            if spec.get(field) and not ok(spec[field]):
                raise HubError("%s is not a %s (%s)" % (spec[field], field, "art:" + ", art:".join(ART_PICTURES) +
                               ", or preset:" + ", preset:".join(PICTURE_PRESETS) if field == "picture" else "#rrggbb"))
        if spec.get("tool") and str(spec["tool"]) not in TOOLS_INFO:
            raise HubError("no tool called %s. Tools: %s" % (spec["tool"], ", ".join(TOOLS_INFO)))
        custom[name] = clean_role(spec)
        if custom[name] is None:
            del custom[name]
            raise HubError("a role needs a description: what the agent is told to do")
        return {"role": dict(custom[name], name=name)}

    if op == "create":
        name = role_name(data.get("name"))
        if name in table:
            raise HubError("there is a role called %s already" % name)
        answer = keep(name, {k: data.get(k) for k in ROLE_FIELDS})
    elif op == "edit":
        name = existing()
        answer = keep(name, dict(table[name], **{k: data[k] for k in ROLE_FIELDS if k in data}))
    elif op == "duplicate":
        name = existing()
        if data.get("new"):
            new = role_name(data["new"])
        else:
            new, number = name + "-copy", 2
            while new in table:
                new, number = "%s-copy-%d" % (name, number), number + 1
            new = role_name(new[:32])
        if new in table:
            raise HubError("there is a role called %s already" % new)
        answer = keep(new, dict(table[name], label=table[name]["label"] + " (copy)"))
    elif op == "delete":
        name = existing()
        moved = sorted(n for n, r in table.items() if r["reports_to"] == name and n != name)
        for other in moved:  # the roles under it move up to the role it reported to
            custom[other] = clean_role(dict(table[other], reports_to=table[name]["reports_to"]))
        if name in packs[project_pack(config, packs)]["roles"]:
            custom[name] = {"deleted": True}  # one of the pack's: kept away
        else:
            custom.pop(name, None)
        answer = dict({"deleted": name}, **({"moved": moved} if moved else {}))
    elif op == "import":
        rows = _import_rows(data.get("roles"))
        for row in rows.values():  # one role exported alone may name a role this project does not have
            if row["reports_to"] not in table and row["reports_to"] not in rows:
                row["reports_to"] = ""
        custom.update(rows)
        answer = {"imported": sorted(rows)}
    elif op == "pack":
        pid = str(data.get("pack") or "")
        find_pack(pid, packs)
        config["pack"] = pid
        config["roles"] = {}  # a project starts over from its new pack
        answer = roles_listing(config, packs, role_table(config, packs))
    else:
        raise HubError("op is list, create, edit, duplicate, delete, import, export, pack or save_pack")
    if op in ("create", "edit", "duplicate", "import"):
        written = answer.get("imported") or [answer["role"]["name"]]
        check_role_tree(_raw_table(config, packs), written)
        if "role" in answer:  # as the project has it: powers by its name when it has none saved
            row = role_table(config, packs)[answer["role"]["name"]]
            answer["role"].update(powers=row["powers"], reports_to=row["reports_to"])
    return answer, {"changed": True}


def _raw_table(config, packs):
    """role_table, but with reports_to as written, so check_role_tree sees a missing role or a loop."""
    table = role_table(config, packs)
    custom = config.get("roles") if isinstance(config.get("roles"), dict) else {}
    for name, row in table.items():
        spec = custom.get(name) if row["source"] == "yours" else packs[project_pack(config, packs)]["roles"].get(name)
        row["reports_to"] = clean_reports_to((spec or {}).get("reports_to"))
    return table


# os.open's files in binary mode on Windows, where a file opened without it is in text mode: Python's own newline
# translation then doubles every line end (\r\r\n), and a byte 10 in an image becomes 13 10.
O_BINARY = getattr(os, "O_BINARY", 0)
CONFIG_LOCK = threading.RLock()  # a change to a config.json, read and written whole: one at a time in this process


def save_config(config, root=None):
    path = (root or home()) / "config.json"
    write_json(path, config, private=True)  # the project's settings, and the bridge's token when there is one


def change_config(change, root=None):
    """change(config) on a config.json, read and written whole one change at a time (CONFIG_LOCK), so a change made
    meanwhile is never written over with an old copy. Not written when change returns False. Returns the config."""
    with CONFIG_LOCK:
        config = load_config(root)
        if change(config) is not False:
            save_config(config, root)
    return config


def token_path(name, root=None):
    """Owner's token, or a place's token (a place is one joined folder on one machine)."""
    return (root or home()) / "tokens" / ("%s.token" % (name if name == OWNER else "place-" + name))


def new_token():
    """A random token that never starts with "-": `crewchat stdio --url URL --token TOKEN` would read it as an option
    (1 token in 64 begins with one)."""
    while True:
        token = secrets.token_urlsafe(32)
        if not token.startswith("-"):
            return token


def ensure_token(name, root=None):
    """Create the token if there is none. True if one was created."""
    path = token_path(name, root)
    if path.exists():
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(str(path), O_BINARY | os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(fd, "w") as f:
        f.write(new_token() + "\n")
    return True


def read_token(name, root=None):
    try:
        return token_path(name, root).read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def list_places(root=None):
    folder = (root or home()) / "tokens"
    try:
        return sorted(p.name[len("place-"):-len(".token")] for p in folder.glob("place-*.token"))
    except OSError:
        return []


class Roster:
    """Project settings and the tokens that may connect, re-read when they change on disk."""

    def __init__(self, root=None):
        self.root = Path(root) if root else home()
        self._stamp = None
        self.project = ""
        self.forget = FORGET_HOURS * 3600
        self.tokens = {}  # sha256(token) -> ("owner", None) or ("place", name)
        self.refresh()

    def _mtimes(self):
        out = []
        paths = [self.root / "config.json", self.root / "tokens"]
        if self.root != home():
            paths.append(home() / "config.json")  # the machine's saved packs
        for path in paths:
            try:
                st = path.stat()
                out.append((st.st_mtime_ns, st.st_ino, st.st_size))  # a file written in place of it is a new inode
            except OSError:
                out.append(None)
        return tuple(out)

    def set(self, key, value):
        """Set one of the project's settings (None: back to its default), and read them again."""
        self.update(key, lambda old: value)

    def update(self, key, change):
        """Set a project setting to change(its value now), the read and the write one change at a time (CONFIG_LOCK):
        two at once (the owner allowing a site while an agent's Allow does) would lose one."""
        def apply(config):
            value = change(config.get(key))
            if value is None:
                config.pop(key, None)
            else:
                config[key] = value
        change_config(apply, self.root)
        self.refresh(force=True)

    def refresh(self, force=False):
        """Read the settings and tokens again if they changed on disk (or force: a change was just
        written, maybe within the clock's last tick)."""
        stamp = self._mtimes()
        if stamp == self._stamp and not force:
            return
        config = load_config(self.root)
        self.config = config
        packs = role_packs()
        self.pack = project_pack(config, packs)
        self.crew = packs[self.pack]["crew"]
        self.role_rows = role_table(config, packs)
        self.roles = role_texts(self.role_rows)
        self.page_roles = [{"name": n, "title": r["label"], "picture": r["picture"], "colour": r["colour"],
                            "tool": r["tool"], "source": r["source"], "powers": r["powers"],
                            "reports_to": r["reports_to"]} for n, r in self.role_rows.items()]
        self.project = str(config["project"])
        self.usage = "off" if config.get("usage") == "off" else "on"  # agents' token counts kept (X4)
        self.edit_tracking = config.get("edit_tracking") if config.get("edit_tracking") in ("on", "off") else "auto"
        try:
            self.forget = max(1.0, float(config["forget_hours"])) * 3600
        except (TypeError, ValueError):
            self.forget = FORGET_HOURS * 3600
        self.tokens = {}
        owner = read_token(OWNER, self.root) or read_token(OWNER)  # projects/<id> use the machine's
        if owner:
            self.tokens[sha(owner)] = ("owner", None)
        for place in list_places(self.root):
            token = read_token(place, self.root)
            if token:
                self.tokens[sha(token)] = ("place", place)
        self._stamp = stamp

    @property
    def places(self):
        return sorted(name for kind, name in self.tokens.values() if kind == "place")

    @property
    def max_chain(self):
        try:
            return max(1, min(MAX_CHAIN_LIMIT, int(self.config.get("max_chain", MAX_CHAIN))))
        except (TypeError, ValueError):
            return MAX_CHAIN


def list_projects(base=None):
    """Every project on this machine, first one first: [{id, name, root, chat}], where chat is
    the key folders are filed under ("" for the first project, else its id)."""
    base = Path(base) if base else home()
    out = []
    if (base / "config.json").exists():
        name = str(load_config(base)["project"])
        out.append({"id": project_id(name), "name": name, "root": base, "chat": ""})
    for path in project_folders(base / PROJECTS_DIR):
        config = load_config(path)
        if not config.get("reserved"):  # the shared notes' project (L1) is crewchat's, never one of the owner's
            out.append({"id": path.name, "name": str(config["project"]), "root": path, "chat": path.name})
    return out


def ensure_shared_project(base=None):
    """The reserved project whose log holds the process notes the owner shares with all projects (L1): made on every
    machine, so its log links with the others' like any project's (by its name). Nobody connects folders to it, and
    it is listed nowhere. Returns its folder."""
    base = Path(base) if base else home()
    for path in project_folders(base / PROJECTS_DIR):
        if load_config(path).get("reserved") == "processes":
            return path
    return create_project(SHARED_PROJECT, base, reserved="processes")["root"]


def project_folders(folder):
    """The project folders in projects/, sorted: each has a config, and none is one being made.
    The command line and the server both go by this, so they never disagree on what is a project."""
    if not folder.is_dir():
        return []
    return sorted(p for p in folder.iterdir() if not p.name.startswith(".") and (p / "config.json").exists())


def find_chat(text, base=None):
    """A project by id or name (any case), or None."""
    want = str(text or "").strip().lower()
    return next((p for p in list_projects(base) if want in (p["id"], p["name"].lower())), None)


def create_project(name, base=None, pack=DEFAULT_PACK, reserved=""):
    """A new, empty project called name, its roles from pack, in projects/<id>/. Returns its
    list_projects() entry ({root} only for a reserved one, which list_projects leaves out)."""
    base = Path(base) if base else home()
    folder = base / PROJECTS_DIR
    folder.mkdir(parents=True, exist_ok=True)
    # Every project's id (the first one has no folder here), and every other folder in projects/:
    # nothing can be moved onto one either.
    taken = {p["id"] for p in list_projects(base)} | {p.name for p in folder.iterdir()}
    pid, number = project_id(name), 2
    while pid in taken:
        pid, number = "%s-%d" % (project_id(name)[:36], number), number + 1
    cutoff = time.time() - 600
    for old in folder.glob(NEW_PROJECT + "*"):  # left by a create that failed (before 0.11.3, or killed)
        try:
            if old.stat().st_mtime < cutoff:
                shutil.rmtree(str(old), ignore_errors=True)
        except OSError:
            pass
    # Built under another name and moved in whole: a running server sees it complete or not at all.
    temp = Path(tempfile.mkdtemp(prefix=NEW_PROJECT, dir=str(folder)))
    try:
        (temp / "tokens").mkdir()
        try:  # who joins: as the host's first project says (crewchat setup --join), else crewchat's own agents only
            join = load_config(base).get("join") if (base / "config.json").exists() else None
        except (OSError, ValueError):
            join = None
        save_config(dict({"project": str(name), "forget_hours": FORGET_HOURS, "join": join if join in JOIN_MODES else "own"},
                         **({"pack": pack} if pack != DEFAULT_PACK else {}), **({"reserved": reserved} if reserved else {})),
                    temp)
        if os.name != "nt":
            os.chmod(temp, 0o700)
            os.chmod(temp / "tokens", 0o700)
        for _ in range(49):
            try:
                os.replace(str(temp), str(folder / pid))
                break
            except PermissionError:
                # Windows: a virus scanner or the search indexer may still hold the new config
                # open, and a folder cannot be renamed until it lets go. That takes a moment.
                time.sleep(0.1)
        else:
            os.replace(str(temp), str(folder / pid))
    except BaseException:
        shutil.rmtree(str(temp), ignore_errors=True)
        raise
    if reserved:
        return {"id": pid, "root": folder / pid}
    return next(p for p in list_projects(base) if p["id"] == pid)


def split_list(text):
    """A comma-separated list (task ids, areas) as a clean list."""
    if isinstance(text, (list, tuple)):
        text = ",".join(str(t) for t in text)
    return [part.strip().lstrip("#") for part in str(text or "").split(",") if part.strip() and part.strip() != "-"]


def lease_paths(text):
    """The paths and globs of a file lease (W8), as given (app/, src/**/Outbox*.kt, *.md): relative to the project,
    with / between folders. Raises HubError for one that leaves the project."""
    paths = []
    for part in split_list(text):
        path = part.replace("\\", "/")
        while path.startswith("./"):
            path = path[2:]
        if not path or len(path) > 200 or path.startswith("/") or re.match(r"^[A-Za-z]:", path) \
                or ".." in path.split("/") or "\0" in path:
            raise HubError("a lease names files in the project, relative to it (app/, src/**/*.kt): not %s" % part)
        if path not in paths:
            paths.append(path)
    if len(paths) > MAX_LEASE_PATHS:
        raise HubError("a lease names at most %d paths or globs" % MAX_LEASE_PATHS)
    return paths


def lease_covers(pattern, path):
    """Does a lease's path or glob cover a file? A folder covers what is in it (app/ or app); a glob's * and ? stay in
    one folder and ** crosses them; a glob with no / matches a file's name in any folder, as in .gitignore."""
    if not any(c in pattern for c in "*?"):
        top = pattern.rstrip("/")
        return path == top or path.startswith(top + "/")
    out, i = "", 0
    while i < len(pattern):
        if pattern.startswith("**/", i):
            out, i = out + "(?:.*/)?", i + 3
        elif pattern.startswith("**", i):
            out, i = out + ".*", i + 2
        elif pattern[i] == "*":
            out, i = out + "[^/]*", i + 1
        elif pattern[i] == "?":
            out, i = out + "[^/]", i + 1
        else:
            out, i = out + re.escape(pattern[i]), i + 1
    found = re.fullmatch(out, path) or ("/" not in pattern.rstrip("/") and re.fullmatch(out, path.rsplit("/", 1)[-1]))
    return bool(found)


def leases_overlap(a, b):
    """Could two leases' paths or globs name the same file? Exactly for paths; for a glob, when either covers the other
    as written (src/** and src/app.py), which leaves some overlaps of two globs unseen."""
    return a.rstrip("/") == b.rstrip("/") or lease_covers(a, b.rstrip("/")) or lease_covers(b, a.rstrip("/"))


# A Jira ticket on a task (J1): its key (PROJ-123), from the key itself or from an address that names it.
JIRA_KEY = re.compile(r"(?<![A-Za-z0-9_-])([A-Z][A-Z0-9_]{1,19}-[1-9][0-9]{0,8})(?![A-Za-z0-9_-])")
JIRA_IN_URL = re.compile(r"/browse/([A-Z][A-Z0-9_]{1,19}-[1-9][0-9]{0,8})(?![A-Za-z0-9_-])"
                         r"|[?&](?:selectedIssue|issueKey)=([A-Z][A-Z0-9_]{1,19}-[1-9][0-9]{0,8})(?![A-Za-z0-9_-])")
JIRA_ADDRESS = re.compile(r"https?://[^\s<>\"'()]+")


def jira_ticket(ref, site=""):
    """(key, address) of the Jira ticket a text names: an address with /browse/KEY (or ?selectedIssue=KEY) in it, or a
    bare key, alone, which gets an address only when the project's Jira site is known (site: its host). ("", "") when
    it names none. The address is always https://HOST/browse/KEY, on the host the text named, so nothing else in a
    pasted address (a query, a fragment) is kept."""
    text = " ".join(str(ref or "").split())
    for url in JIRA_ADDRESS.findall(text):
        found = JIRA_IN_URL.search(url)
        host = site_of(url)
        if found and host:
            key = found.group(1) or found.group(2)
            return key, "%s://%s/browse/%s" % ("http" if url.lower().startswith("http:") else "https", host, key)
    if JIRA_KEY.fullmatch(text.upper()):
        key = text.upper()
        return key, ("https://%s/browse/%s" % (site, key) if site else "")
    return "", ""


def jira_http(method, url, json_body=None, form=None, token="", headers=None, want_headers=False, who="Atlassian"):
    """One request to Atlassian (J3), or Google (G1, who): JSON or a form in, JSON (or an MCP event stream's last
    message) out. Raises HubError with what went wrong (the service's own reason, when it gives one), never with what
    was sent."""
    send = {"Accept": "application/json, text/event-stream", "User-Agent": "crewchat/%s" % __version__}
    data = None
    if json_body is not None:
        data, send["Content-Type"] = json.dumps(json_body).encode("utf-8"), "application/json"
    elif form is not None:
        data, send["Content-Type"] = urllib.parse.urlencode(form).encode("utf-8"), "application/x-www-form-urlencoded"
    if token:
        send["Authorization"] = "Bearer " + token
    send.update(headers or {})
    req = urllib.request.Request(url, data=data, headers=send, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode("utf-8")
            kind, got = resp.headers.get("Content-Type", ""), resp.headers
    except urllib.error.HTTPError as e:
        raise HubError("%s refused (HTTP %d%s)" % (who, e.code, http_reason(e)))
    except (urllib.error.URLError, OSError) as e:
        raise HubError("could not reach %s (%s)" % (who, getattr(e, "reason", e)))
    try:
        if "text/event-stream" in kind:
            events = [json.loads(line[5:]) for line in raw.splitlines() if line.startswith("data:") and line[5:].strip()]
            answer = events[-1] if events else None
        else:
            answer = json.loads(raw) if raw.strip() else None
    except ValueError:
        raise HubError("%s answered with something that is not JSON" % who)
    return (answer, got) if want_headers else answer



def atlassian_https(url):
    """Whether an address is https on atlassian.com (or a name under it): where crewchat sends the owner to sign in."""
    parts = urllib.parse.urlsplit(str(url or ""))
    host = (parts.hostname or "").lower()
    return parts.scheme == "https" and (host == "atlassian.com" or host.endswith(".atlassian.com"))


def jira_auth_server():
    """Where Atlassian's v2 MCP server has its users sign in (J3): its protected-resource document names the sign-in
    server (RFC 9728), whose own document gives the addresses to authorize, swap codes and register (RFC 8414).
    Returns {"authorization", "token", "registration"}. Raises HubError."""
    parts = urllib.parse.urlsplit(JIRA_MCP)
    meta = jira_http("GET", "%s://%s/.well-known/oauth-protected-resource%s" % (parts.scheme, parts.netloc, parts.path))
    issuer = str(((meta or {}).get("authorization_servers") or [""])[0] if isinstance(meta, dict) else "")
    if not atlassian_https(issuer):
        raise HubError("Atlassian's MCP server did not say where to sign in")
    at = urllib.parse.urlsplit(issuer)
    found = jira_http("GET", "%s://%s/.well-known/oauth-authorization-server%s" % (at.scheme, at.netloc, at.path.rstrip("/")))
    where = {k: str((found or {}).get(k + "_endpoint") or "") if isinstance(found, dict) else ""
             for k in ("authorization", "token", "registration")}
    if not all(atlassian_https(u) for u in where.values()):
        raise HubError("Atlassian's sign-in server did not give its addresses")
    return where

def http_reason(error):
    """The reason an HTTP error's JSON body gives ({"error": {"message": ...}}, or error_description), short: ": ..."."""
    try:
        data = json.loads(error.read().decode("utf-8", "replace")[:20000])
    except Exception:  # no body, or not JSON
        return ""
    found = data.get("error") if isinstance(data, dict) else None
    text = found.get("message") if isinstance(found, dict) else data.get("error_description") if isinstance(data, dict) else ""
    text = " ".join(str(text or "").split())[:200]
    return ": " + text if text else ""


class JiraMcp:
    """A minimal MCP client of Atlassian's server over streamable HTTP (J3): initialize, then list and call tools.
    access(fresh) gives the bearer token; one 401 refreshes it."""

    def __init__(self, access):
        self.access, self.session, self.rid, self._tools = access, "", 0, None

    def _rpc(self, method, params=None, note=False):
        """One request in this session. A session Atlassian no longer knows (HTTP 404, as MCP says) starts again
        once."""
        try:
            return self._rpc_once(method, params, note)
        except HubError as e:
            if "HTTP 404" not in str(e) or not self.session or method == "initialize":
                raise
            self.session = ""
            self._start()
            return self._rpc_once(method, params, note)

    def _rpc_once(self, method, params=None, note=False):
        body = {"jsonrpc": "2.0", "method": method}
        if params is not None:
            body["params"] = params
        if not note:
            self.rid += 1
            body["id"] = self.rid
        for fresh in (False, True):
            headers = {"Mcp-Session-Id": self.session} if self.session else {}
            try:
                answer, got = jira_http("POST", JIRA_MCP, json_body=body, token=self.access(fresh), headers=headers,
                                        want_headers=True)
            except HubError as e:
                if "HTTP 401" not in str(e):
                    raise
                if not fresh:
                    continue  # its access token ran out early: refreshed once
                raise HubError("Atlassian refused the sign-in: sign in again on the Jira card")
            if got.get("Mcp-Session-Id"):
                self.session = got.get("Mcp-Session-Id")
            if note:
                return None
            if not isinstance(answer, dict) or "error" in answer:
                raise HubError("Atlassian's MCP server: %s" % ((answer or {}).get("error") or {}).get("message", "no answer"))
            return answer.get("result") or {}

    def _start(self):
        if not self.session:
            self._rpc("initialize", {"protocolVersion": "2025-06-18", "capabilities": {},
                                     "clientInfo": {"name": "crewchat", "version": __version__}})
            self._rpc("notifications/initialized", note=True)

    def tools(self):
        """The server's tools' names, asked once in the session."""
        if self._tools is None:
            self._start()
            self._tools = [str(t.get("name")) for t in self._rpc("tools/list").get("tools") or [] if isinstance(t, dict)]
        return self._tools

    def call(self, name, arguments):
        self._start()
        return self._rpc("tools/call", {"name": name, "arguments": arguments})


def mcp_text(result):
    """The text of an MCP tool result."""
    return "\n".join(str(c.get("text") or "") for c in (result or {}).get("content") or []
                     if isinstance(c, dict) and c.get("type") == "text")


def jira_cloud_id(text, site):
    """The cloud id of the Jira site from getAccessibleAtlassianResources' answer, or ""."""
    try:
        sites = json.loads(text)
    except ValueError:
        return ""
    for entry in sites if isinstance(sites, list) else []:
        if isinstance(entry, dict) and site_of(str(entry.get("url") or "")) == site and entry.get("id"):
            return str(entry["id"])
    return ""


def jira_issues(text):
    """(key, summary) of each ticket in a Jira search's answer: its JSON (issues, or nodes under it), else the keys
    named in the text."""
    try:
        data = json.loads(text)
    except ValueError:
        data = None
    issues = data.get("issues") if isinstance(data, dict) else data if isinstance(data, list) else None
    if isinstance(issues, dict):
        issues = issues.get("nodes") or issues.get("issues")
    found = []
    if isinstance(issues, list):
        for issue in issues:
            key = str((issue or {}).get("key") or "") if isinstance(issue, dict) else ""
            if JIRA_KEY.fullmatch(key):
                fields = issue.get("fields") if isinstance(issue.get("fields"), dict) else issue
                found.append((key, " ".join(str(fields.get("summary") or "").split())[:200]))
        return found
    seen = []
    for key in JIRA_KEY.findall(text or ""):
        if key not in seen:
            seen.append(key)
    return [(key, "") for key in seen]


def like_escape(text):
    """Text for a LIKE pattern (ESCAPE '\\'): its \\, % and _ match only themselves."""
    return text.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def area_key(area):
    return area.strip().strip("/").lower() + "/"


def areas_overlap(a, b, linked=None):
    """Do two tasks touch the same files? Areas are path prefixes; one inside another overlaps. With linked (the
    code map's, C1), so does an area with a file that imports one of the other's, or is imported by it."""
    if any(area_key(x).startswith(area_key(y)) or area_key(y).startswith(area_key(x)) for x in a for y in b):
        return True
    return linked is not None and any(linked(x, y) for x in a for y in b)


def area_covered(area, areas):
    """Is this area inside one of these?"""
    return any(area_key(area).startswith(area_key(other)) for other in areas)


MAX_SUGGESTED = 5  # areas suggested for a task at most (C2)


def group_areas(paths, cap=MAX_SUGGESTED):
    """The areas of the files a task changed: each file's folder (a file at the top stays a file), folders inside
    another counted with it, and the deepest raised to their parent until at most cap are left; if there are
    still more, the cap most edited."""
    def tidy(counts):
        out = {}
        for area in sorted(counts, key=len):
            outer = next((o for o in out if o.endswith("/") and area.startswith(o)), area)
            out[outer] = out.get(outer, 0) + counts[area]
        return out
    counts = {}
    for path in paths:
        area = path.rsplit("/", 1)[0] + "/" if "/" in path else path
        counts[area] = counts.get(area, 0) + 1
    counts = tidy(counts)
    while len(counts) > cap:
        deepest = max(area.count("/") for area in counts)
        if deepest <= 1:  # only top folders and files left
            break
        raised = {}
        for area, n in counts.items():
            if area.count("/") == deepest:
                area = area[:-1].rsplit("/", 1)[0] + "/"
            raised[area] = raised.get(area, 0) + n
        counts = tidy(raised)
    return sorted(sorted(counts, key=lambda area: (-counts[area], area))[:cap])


def project_id(name):
    """The id of a project in URLs, commands and folder names: its name, made safe."""
    return slug(name, 40, "project")


class Project:
    """One project's chat: its settings and tokens (a Roster) and its messages and agents (a Hub)."""

    def __init__(self, root, primary=False):
        self.root = Path(root)
        self.primary = primary
        self.roster = Roster(self.root)
        self.hub = Hub(self.roster)
        self.hub.chat_key = "" if primary else self.root.name  # how this machine files its folders
        self.hub.machine_root = self.root if primary else self.root.parent.parent

    @property
    def id(self):
        return self.root.name if not self.primary else project_id(self.roster.project)

    @property
    def name(self):
        return self.roster.project


class Projects:
    """Every project on this machine. The first lives in the crewchat home folder itself (so a
    machine set up before projects keeps its chat as it is); each other one in projects/<id>/,
    laid out the same way, and is picked up as soon as its folder appears."""

    def __init__(self, root=None):
        self.base = Path(root) if root else home()
        if (self.base / "config.json").exists():
            try:
                ensure_shared_project(self.base)
            except OSError as e:  # shared notes wait; everything else works
                sys.stderr.write("%s could not make the shared notes' project: %s\n" % (now_iso(), e))
        self.primary = Project(self.base, primary=True)
        self.others = {}  # the reserved project too (it links like the others), but listed() leaves it out
        self.shared = None  # the reserved project: the process notes shared with all projects (L1)
        self._stamp = None
        self.lock = threading.Lock()
        self.on_change = None  # called after projects appear or go (cmd_serve: their links follow)
        self.refresh()

    def refresh(self):
        folder = self.base / PROJECTS_DIR
        try:
            stamp = folder.stat().st_mtime_ns
        except OSError:
            stamp = 0
        if stamp and time.time() - stamp / 1e9 < 2:
            # Freshly changed: on a disk whose clock ticks once a second, a project can appear
            # without the folder's time moving, so for a moment the listing counts too.
            try:
                stamp = (stamp, tuple(sorted(p.name for p in folder.iterdir())))
            except OSError:
                pass
        if stamp == self._stamp:
            return
        with self.lock:
            if stamp == self._stamp:  # another request got here first and did it
                return
            found = project_folders(folder) if stamp else []
            for path in found:
                if path.name not in self.others:
                    self.others[path.name] = Project(path)
            names = {p.name for p in found}
            for gone in [k for k in self.others if k not in names]:
                del self.others[gone]  # its folder was removed: its tokens stop working
            self.shared = next((p for p in self.others.values() if p.roster.config.get("reserved") == "processes"), None)
            for project in [self.primary] + list(self.others.values()):
                project.hub.shared_hub = self._shared_hub
                project.hub.on_published = self._shared_published
            if self.shared is not None:
                self.shared.hub.on_processes = self._shared_changed
            self._stamp = stamp
        if self.on_change is not None:
            self.on_change(self)

    def all(self):
        self.refresh()
        return self.listed()

    def listed(self):
        """The projects as last read, without reading the folder again (not the reserved one; under the lock: a link's
        threads ask while a refresh may change them)."""
        with self.lock:
            return [self.primary] + [self.others[k] for k in sorted(self.others) if self.others[k] is not self.shared]

    def _shared_hub(self):
        return self.shared.hub if self.shared is not None else None

    def _shared_published(self, note):
        """A note shared with all projects was approved on this machine: each project's agents working in its areas
        hear of it (L4)."""
        for project in self.listed():
            project.hub.tell_note_holders(note)

    def _shared_changed(self):
        """A shared note became live or went: it is in every project's folders."""
        for project in self.listed():
            project.hub.refresh_guides()

    def get(self, pid):
        """The project with this id (the first one for None or ""), or None."""
        if not pid:
            return self.primary
        return next((p for p in self.all() if p.id == pid), None)

    def remove(self, pid):
        """The owner removes a project from this machine: its folder moves whole into projects/.removed/, where
        project_folders() no longer sees it, so its chat, tasks and roles are kept and can be moved back by hand.
        Its tokens stop working. Not the first project, which is the crewchat folder itself. Returns the new place."""
        project = self.get(pid) if pid else None
        if project is None:
            raise HubError("there is no project %s" % pid)
        if project.primary:
            raise HubError("%s is this machine's first project, which cannot be removed" % project.name)
        project.hub.flush()  # what waits to be written goes into the folder before it moves
        bin_ = self.base / PROJECTS_DIR / REMOVED_PROJECTS
        place = bin_ / ("%s-%s" % (project.root.name, time.strftime("%Y%m%d-%H%M%S")))
        number = 2
        while place.exists():
            place, number = bin_ / ("%s-%s-%d" % (project.root.name, time.strftime("%Y%m%d-%H%M%S"), number)), number + 1
        with project.hub.lock:  # nothing is written into it while it moves
            bin_.mkdir(parents=True, exist_ok=True)
            try:
                project.hub.close_stores()  # Windows cannot move a folder with a file in it open ("Access is denied")
                retry_on_windows(lambda: os.replace(str(project.root), str(place)))  # a virus scanner, for a moment
            except Exception:
                project.hub.open_stores()  # it stays here
                raise
        self.refresh()
        return place

    def by_token(self, digest):
        """(project, who) for a token's sha256, or (None, None)."""
        for project in self.all():
            project.roster.refresh()
            who = project.roster.tokens.get(digest)
            if who is not None:
                return project, who
        return None, None


