def tools_for(hub, sid, owner=False):
    """The tools a session gets: the lead's and the advisor's have hub_code too; the owner's has everything.
    Remembered, so the session can be told when its role changes what it should have."""
    kind = "lead" if owner else hub.tool_kind(sid)
    hub.listed(sid, kind)
    extra = [GCHAT_TOOL] if "+gchat" in kind else []  # only while the project can post to Google Chat (G2)
    extra += [JIRA_TOOL] if "+jira" in kind else []  # only while the Jira ticket cycle is on (F3)
    if "+crew" in kind:  # a role with the crew power (C10)
        extra = [CREW_TOOL] + extra
    if not kind.startswith("lead"):
        return TOOLS + extra
    return [LEAD_PROCESS if t["name"] == "hub_process" else t for t in TOOLS] + LEAD_TOOLS + extra


def days_arg(data, default=7):
    """The days a report covers, from a request: 1 to USAGE_DAYS."""
    try:
        return max(1, min(USAGE_DAYS, int(data.get("days") or default)))
    except (TypeError, ValueError):
        raise HubError("days is a number")


def int_arg(args, key, default, low, high):
    value = args.get(key, default)
    if isinstance(value, bool) or not isinstance(value, int) or not low <= value <= high:
        raise HubError("%s must be an integer from %d to %d" % (key, low, high))
    return value


MAX_TOOL_OUTPUT = 6000  # characters of messages hub_inbox and hub_history give at once (whole messages)


def whole_lines(lines, limit=MAX_TOOL_OUTPUT):
    """The first lines that fit in limit characters, never cutting one, and always at least one."""
    out, size = [], 0
    for line in lines:
        if out and size + len(line) + 1 > limit:
            break
        out.append(line)
        size += len(line) + 1
    return out


def task_call(args):
    """hub_task's action, and its arguments as the task code below reads them."""
    action = args.get("action")
    if action not in TASK_ACTIONS:
        raise HubError("action is %s" % ", ".join(TASK_ACTIONS))
    if action == "view":
        return "task:view", {"view": args.get("show") or "next"}
    if action == "assign":
        if args.get("title") and args.get("id"):
            raise HubError("assign takes id (a task on the sheet) or title (new work), not both")
        return "task:assign", {"to": args.get("to"), "text": args.get("title"),
                               "task": args.get("parent") if args.get("title") else args.get("id")}
    return "task:" + action, args


def call_tool(hub, sid, name, args, owner=False):
    """Run one tool for a session, or for the owner (the `crewchat` command line)."""
    if not isinstance(args, dict):
        raise HubError("arguments must be an object")
    if name in OLD_TASK_TOOLS:
        raise HubError("%s is now hub_task with action %s: crewchat merged its task tools into one. This session "
                       "has the old tool list; restart it to load the new one." % (name, OLD_TASK_TOOLS[name]))
    if name not in HUB_TOOL_NAMES:
        raise HubError("unknown tool: %s" % name)
    if name == "hub_task":
        name, args = task_call(args)
    if name == "hub_link":
        if owner:
            raise HubError("the owner has no session to link")
        key = args.get("key")
        launched = isinstance(key, str) and key.startswith("start-")  # an agent started from the chat page
        if not launched and hub.closed_to(key):
            raise HubError(NOT_OURS)
        me, note = (hub.start_link if launched else hub.link)(sid, key)
        hub.touch(me, active=True)
        return "%s Who is here:\n%s" % (note, roster_text(hub.rows(), me))
    if not owner and hub.join_mode() == "own" and hub.agent_for(sid, create=False) is None:
        raise HubError(NOT_OURS)  # a session crewchat did not start, in a project that lets only its own agents join
    me = OWNER if owner else hub.agent_for(sid)
    hub.touch(me, active=True)
    if name == "hub_send":
        to = args.get("to")
        folders = None if owner else hub.agent_folders(me)  # None: the owner, who may share any file
        if args.get("files") and folders == []:
            # The paths would be read here, on the host, not where the agent is.
            raise HubError(REMOTE_FOLDER_FILES + " Put the text in the message instead.")
        files = [share_file(hub, path, folders) for path in args.get("files") or []]
        msg = hub.send(me, to, clean_text(to, args.get("text"), me, files), files=files, ask=bool(args.get("ask")),
                       thread=args.get("thread"))
        if not owner:
            hub.gchat_watch(me, msg["text"])  # a pull request named here goes to Google Chat, if the owner wants (G3)
        return "Sent #%s to %s%s.%s" % (msg["id"], to, " with %d file(s)" % len(files) if files else "",
                                         "" if owner else hub.still_asked(me, msg["to"]))
    if name == "hub_profile":
        picture = args.get("picture")
        picture = picture if picture in (None, "initials") else (
            "art:%s" if picture in ART_PICTURES else "preset:%s") % picture
        if args.get("file"):
            folders = hub.agent_folders(me)
            if folders == []:
                raise HubError(REMOTE_FOLDER_FILES)
            check_picture_file(args["file"])
            picture = "file:" + share_file(hub, args["file"], folders)["id"]
        done = hub.set_profile(me, picture, args.get("colour"))
        return "Your profile: picture %s, colour %s." % (done["picture"] or "initials",
                                                         done["colour"] or "the tool's colour")
    if name == "hub_file":
        return open_shared_file(hub, args.get("id"), me)
    if name == "hub_process":
        return process_call(hub, me, args)
    if name == "hub_inbox":
        unread = hub.inbox(me, int_arg(args, "wait_seconds", 0, 0, MAX_WAIT), True)
        if not unread:
            return "No new messages."
        shown = whole_lines([fmt(m, me, True) for m in unread])
        if not args.get("peek"):
            hub.read_to(me, unread[len(shown) - 1]["seq"])  # only what is shown: the rest stays unread
        more = len(unread) - len(shown)
        return (TRUST_NOTE + " Times are UTC.\n\n" + "\n".join(shown)
                + ("\n\n%d more unread: call hub_inbox again." % more if more else ""))
    if name == "task:take":
        if owner:
            raise HubError("the owner posts tasks; agents take them")
        mid = clean_id(args.get("id"))
        hub.take(me, mid)
        return ("Task #%s is yours and everyone has been told. Before any other work, send hub_task "
                "action=update id=%s status=in_progress with one line on your plan; then start.%s%s%s"
                % (mid, mid, hub.reclaim_note(mid), hub.heads_up(me, mid),
                   hub.notes_note(mid) + hub.jira_note(mid, me) + hub.parked_note(mid)))
    if name == "hub_agents":
        return roster_text(hub.rows(), me) or "No agents yet."
    if name == "hub_history" and str(args.get("q") or "").strip():  # every message the chat ever had (W7)
        hits = hub.chat_index.search(args.get("q"))
        if not hits:
            return "Nothing found for that."
        shown = whole_lines([fmt(m, me, True) for m in hits])
        return TRUST_NOTE + " Times are UTC; newest first.\n\n" + "\n".join(shown)
    if name == "hub_history":
        rows = hub.history(int_arg(args, "limit", 20, 1, 50))
        if not rows:
            return "No messages yet."
        shown = whole_lines([fmt(m, me, True) for m in reversed(rows)])[::-1]  # the newest that fit
        left = len(rows) - len(shown)
        return (TRUST_NOTE + " Times are UTC.\n\n"
                + ("(%d older left out: they did not fit)\n" % left if left else "") + "\n".join(shown))
    if name == "task:lease":
        if owner:
            raise HubError("agents lease files; the owner releases a lease from its task on the chat page")
        return hub.lease(me, args.get("areas"), args.get("minutes"), args.get("id"))
    if name == "task:assign":
        to, text = args.get("to"), args.get("text")
        if not text and args.get("task"):
            hub.assign_row(me, to, args.get("task"))
            return "Gave task #%s to %s. They report back to you with hub_task update.%s" % (
                clean_id(args["task"]), to, hub.heads_up(to, clean_id(args["task"])))
        msg = hub.assign(me, to, clean_text(to, text, me), args.get("task"))
        return "Assigned task #%s to %s. They report back to you with hub_task update." % (msg["id"], to)
    if name == "task:view":
        view = args.get("view") or "next"
        if view not in ("next", "mine", "all"):
            raise HubError("view is next, mine or all")
        rows = hub.sheet_rows(me, view if not owner else "all")
        if not rows:
            return {"next": "Nothing on the sheet you can take now. Ask the lead or Owner, or find work and add it "
                    "with hub_task add.", "mine": "You hold no task.", "all": "The task sheet is empty."}[view]
        head = {"next": "Tasks you may take now, top first (hub_task take the first one):",
                "mine": "Your tasks:", "all": "The task sheet, in order:"}[view]
        note = hub.reclaim_note().strip()
        return head + "\n" + "\n".join(sheet_line(r) for r in rows) + ("\n" + note if note else "")
    if name == "task:add":
        msg = hub.add_row(me, args.get("title"), args.get("depends", ""), args.get("areas", ""), args.get("where", ""))
        if args.get("take") and not owner:
            hub.take(me, msg["id"])
            return ("Task #%s is on the sheet and yours. Send hub_task action=update id=%s status=in_progress with your plan, "
                    "then start.%s%s%s" % (msg["id"], msg["id"], hub.reclaim_note(msg["id"]), hub.heads_up(me, msg["id"]),
                                           hub.notes_note(msg["id"]) + hub.jira_note(msg["id"], me)))
        return "Task #%s is on the sheet for whoever can take it." % msg["id"]
    if name == "hub_answer":
        msg = hub.answer(me, args.get("id"), args.get("text"), args.get("verdict") or "")
        return "Answered #%s; %s has it%s." % (msg["answers"], msg["to"],
                                               " (verdict: %s)" % msg["verdict"] if msg.get("verdict") else "")
    if name == "hub_jira":
        return hub.hub_jira(me, args, owner=owner)
    if name == "hub_gchat":
        if not owner and not hub.gchat_ready():
            raise HubError("this project posts to no Google Chat space now: Owner adds one in Project settings")
        out = hub.gchat_post(me, args.get("text"), args.get("url") or "", args.get("title") or "",
                             args.get("space") or "", owner=owner)
        return "Posted to Google Chat, space %s. Everyone in the chat has been told." % out["space"]
    if owner:
        raise HubError("only agents have a status and a name, and ask the advisor")
    if name == "hub_ask":
        question, answer = hub.ask(me, args.get("question"), args.get("task"), args.get("to") or None)
        if answer is None:
            return ("Asked %s (#%s). No answer yet: it comes to your inbox (hub_inbox with wait_seconds). Carry "
                    "on with what does not depend on it." % (question["to"], question["id"]))
        verdict = " Verdict: %s." % VERDICTS[answer["verdict"]] if answer.get("verdict") in VERDICTS else ""
        return "%s answered (#%s):%s\n\n%s" % (answer["from"], answer["id"], verdict, answer["text"])
    if name == "hub_status":
        text = args.get("text")
        if not isinstance(text, str) or len(text) > MAX_STATUS:
            raise HubError("text must be a string of at most %d characters" % MAX_STATUS)
        hub.set_status(me, " ".join(text.split()))
        return "Status set."
    if name == "hub_role":
        role = args.get("role")
        if role is None:
            current = (hub.agents.get(me) or {}).get("role", "")
            roles = hub.roles()
            if current not in roles:
                return "You have no role. Roles: %s." % ", ".join(sorted(roles))
            title, prompt = roles[current]
            with hub.lock:
                tree = hub._tree_note(current) + hub._crew_note(current)
            return "Your role: %s.\n\n%s%s" % (title, prompt, tree)
        if not isinstance(role, str):
            raise HubError("role must be a string")
        msg = hub.set_role(me, me, role.strip().lower())
        return msg["text"]
    if name == "hub_crew":
        if owner:
            raise HubError("the owner adds agents with + New agent and removes them from their cards")
        action = args.get("action")
        if action == "list":
            return hub.crew_list(me)
        if action == "add":
            return hub.crew_add(me, args.get("role"), args.get("task"), args.get("name"), args.get("folder"),
                                args.get("jira"), args.get("browser"), args.get("mobile"))
        if action == "remove":
            return hub.crew_remove(me, args.get("name"))
        raise HubError("action is %s" % ", ".join(CREW_ACTIONS))
    if name == "hub_code":
        if not owner and not hub.tool_kind(sid).startswith("lead"):
            raise HubError("hub_code is for the lead and the advisor")
        action = args.get("action")
        if action == "history":
            return hub.file_history(args.get("path"))
        if action == "split":
            count = args.get("count")
            if count is not None:
                count = int_arg(args, "count", 4, 2, 8)
            return hub.split_task(args.get("id"), count)
        raise HubError("action is history or split")
    if name == "task:park":  # a task that waits on the owner goes back in the open queue (C11)
        return hub.park(me, args.get("id"), args.get("note") or "")
    if name == "task:areas":
        mid, areas = hub.set_areas(me, args.get("id"), args.get("areas", ""), args.get("accept") is True)
        return "Task #%s's files: %s." % (mid, ", ".join(areas))
    if name == "task:return":
        return return_call(hub, me, args, owner)
    if name == "task:update":
        note = args.get("note") or ""
        if not isinstance(note, str) or len(note) > MAX_TEXT:
            raise HubError("note must be a string of at most %d characters" % MAX_TEXT)
        msg, to = hub.update(me, args.get("id"), args.get("status"), note.strip() or STATUSES.get(args.get("status"), ""))
        if not owner:
            hub.gchat_watch(me, note)  # G3, as for hub_send
        hard = hub.was_hard(msg["task"]) if msg["status"] == "done" and not owner else ""
        return "Task #%s marked %s; %s has been told.%s" % (msg["task"], STATUSES[msg["status"]],
                                                            "the owner" if to == OWNER else to,
                                                            NOTE_PROMPT % hard if hard else "")
    new = args.get("name")
    hub.rename(me, new)
    return "You are now %s. Everyone has been told.%s" % (new, SESSION_NAME_NOTE % new)


def return_call(hub, me, args, owner=False):
    """hub_task return (Q1, Q2): a tester sends a task back to its holder with what failed and screenshots, or the holder
    sends it back to its tester, fixed; with live, the browser page or the device goes with it, as it is."""
    note = args.get("note") or ""
    if not isinstance(note, str) or not note.strip() or len(note) > MAX_TEXT:
        raise HubError("return needs a note of at most %d characters: the steps, what you expected and what happened; "
                       "or what you fixed and how to check it" % MAX_TEXT)
    if not isinstance(args.get("files") or [], list) or len(args.get("files") or []) > MAX_FILES:
        raise HubError("files is a list of at most %d paths" % MAX_FILES)
    folders = None if owner else hub.agent_folders(me)
    if args.get("files") and folders == []:
        raise HubError(REMOTE_FOLDER_FILES + " Put what they show in the note instead.")
    files = [share_file(hub, path, folders) for path in args.get("files") or []]
    msg = hub.return_task(me, args.get("id"), note.strip(), files, args.get("to") or None, args.get("live") is True)
    shown = "%s has it%s" % ("the owner" if msg["to"] == OWNER else msg["to"],
                             " with %d screenshot(s)" % len(files) if files else "")
    if msg["status"] == "blocked":
        return ("Task #%s has been sent back %d times, so it went to %s to step in instead of to its developer; %s."
                % (msg["task"], MAX_RETURNS, "the owner" if msg["to"] == OWNER else msg["to"], shown))
    handed = [w for w in ("the page %s" % msg["page"] if msg.get("page") else "",
                          "%s%s" % (msg["device"], " with %s in front" % msg["app"] if msg.get("app") else "")
                          if msg.get("device") else "") if w]
    live = ""
    if args.get("live") is True:
        live = (" Handed over: %s. Stop using them now." % " and ".join(handed) if handed else
                " You held no browser page or device to hand over, so only the note went.")
    if msg["status"] == "in_progress":
        return "Sent task #%s back to %s (round %s of %d); %s.%s%s" % (msg["task"], msg["to"], msg["back"], MAX_RETURNS,
                                                                         shown, live, "" if owner else RETURN_FACT_PROMPT)
    return "Task #%s is back with %s to test again; %s.%s" % (msg["task"], msg["to"], shown, live)


# Asked when a hard task is done (L3), and only then: asked every time, agents learn to skip it. Two lines at most.
NOTE_PROMPT = ("\n%s. Did you work out a process another agent would need (steps, commands, a trap), or find out "
               "something the next agent would trip over? If so, record it: hub_process propose (for one or two lines, "
               "note kind fact).")
# Asked when a tester sends a task back (L8): why it failed is often something every developer should know.
RETURN_FACT_PROMPT = (" If what failed is something other agents would trip over too (not just this bug), record it "
                      "as a fact: hub_process propose with note kind fact, fact, and its areas.")
SLOW_TASK = 2.0  # a task that took this many times the median of the tasks done before it looked hard (L3)
SLOW_TASKS_KNOWN = 3  # tasks done before, at least, for the median to count


def process_line(row):
    """One process note, as hub_process list and find show it."""
    live = "" if row["live"] in (0, row["version"]) else ", v%d live" % row["live"]
    if row.get("stale"):
        live += ", may be out of date: " + row["stale"]
    wait = (" (waits for %s%s)" % ("the owner" if row["approver"] == "owner" else "the lead",
                                   ": " + row["why"] if row["why"] else "")) if row["state"] == "proposed" else ""
    return "- %s v%d, %s%s%s%s: %s" % (row["name"], row["version"], row["state"], live, wait,
                                       ", all projects" if row["scope"] == "shared" else "", row["when"])


def process_call(hub, me, args):
    """hub_process (L2): propose, update, list, get, find; the lead's also approve, decline and retire."""
    action, name, note = args.get("action"), args.get("name"), args.get("note")
    if action not in PROCESS_ACTIONS + LEAD_PROCESS_ACTIONS:
        raise HubError("action is %s" % ", ".join(PROCESS_ACTIONS))
    if note is not None and not isinstance(note, dict):
        raise HubError("note is an object: when, steps, commands, pitfalls, areas, scope (a fact: kind fact, fact, "
                       "areas, roles)")
    if note and "command" in note:
        raise HubError("only the owner makes a note's commands a project command")
    if action == "list":
        rows = hub.process_rows()
        if not rows:
            return "No process notes yet. Worked something out the hard way? hub_process propose."
        return "The process notes (hub_process get NAME for one):\n" + "\n".join(process_line(r) for r in rows)
    if action == "find":
        found = hub.find_processes(name)
        return ("Notes that may help (hub_process get NAME):\n" + "\n".join(process_line(r) for r in found) if found
                else "No note matches. When you work it out, hub_process propose it.")
    if not isinstance(name, str) or not name.strip():
        raise HubError("name the note, like release-build")
    if action == "get":
        v = hub.process_note(name)
        state = v["state"] + ("" if v["live"] in (0, v["version"]) else "; agents get v%d until this one is approved"
                              % v["live"])
        return "\n".join(process_body(v)) + "\n\nState: %s." % state
    if action == "propose":
        v, who, why = hub.propose_process(me, dict(note or {}, name=name, commit=hub.agent_commit(me)))
    elif action == "update":
        v, who, why = hub.update_process(me, name, dict(note or {}, commit=hub.agent_commit(me)))
    elif action == "report":
        return hub.report_process(me, name, (note or {}).get("ok"), (note or {}).get("why", ""))
    elif action == "approve":
        return hub.approve_process(me, name)
    elif action == "decline":
        hub.decline_process(me, name)
        return "Declined %s's proposed version; its author has been told." % name
    else:
        hub.retire_process(me, name)
        return "Retired %s: agents no longer get it." % name
    if me == OWNER:
        return "%s v%d is approved: every agent's folder gets it." % (v["name"], v["version"])
    return "%s v%d is proposed: %s approves it%s. Until then agents %s." % (
        v["name"], v["version"], "the owner" if who == "owner" else "the lead", " (%s)" % why if why else "",
        "keep the approved version" if v["version"] > 1 else "do not get it")


def sheet_line(row):
    """One task on the sheet, as agents and the command line see it."""
    extra = ["from %s" % row["from"]]
    if row["holder"]:
        extra.append("held by %s" % row["holder"])
    if row.get("reclaimed"):
        extra.append("reclaimed from %s" % row["reclaimed"])
    if row.get("parked"):
        extra.append("parked while %s waited on Owner: \"%s\"; %s" % (
            row["parked"], row.get("pending", "")[:200],
            "Owner answered: \"%s\"" % row["owner_said"][:300] if row.get("owner_said") else "not answered yet"))
    if row.get("check"):
        extra.append("advisor: %s" % VERDICTS.get(row.get("verdict"), "asked"))
    if row.get("reclaim"):
        extra.append("never reclaimed" if row["reclaim"] == "off" else "reclaimed after %s min of silence" % row["reclaim"])
    if row["depends"]:
        extra.append("waits for " + ", ".join("#" + d for d in row["depends"]))
    if row.get("blocker"):
        extra.append("held back: " + row["blocker"])
    if row["areas"]:
        extra.append("files " + ", ".join(row["areas"]))
    if row.get("suggested"):
        extra.append("suggested files " + ", ".join(row["suggested"]))
    if row.get("jira"):
        extra.append("Jira %s" % (row.get("jira_url") or row["jira"]))
    if row["where"]:
        extra.append("on " + row["where"])
    if row["to"] != "all":
        extra.append("for " + row["to"])
    return "#%s [%s] %s (%s)" % (row["id"], row["status"], row["title"], "; ".join(extra))


def crewchat_homes(hub):
    """crewchat's own folders for this hub, which hold its keys: the crewchat home and the project's."""
    return {home().resolve(), hub.roster.root.resolve()}


def stored_tokens(roots):
    """Every token kept under these crewchat folders (the owner's, and each place's), and the browser bridge's, as
    bytes."""
    found = set()
    for root in roots:
        for path in itertools.chain(root.glob("tokens/*.token"), root.glob("projects/*/tokens/*.token")):
            try:
                token = path.read_bytes().strip()
            except OSError:
                continue
            if len(token) >= 20:  # an empty or hand-made stub must not match every file
                found.add(token)
    bridge = browser_token().encode("utf-8")  # the Playwright bridge's: it drives the owner's Chrome (B1)
    if len(bridge) >= 20:
        found.add(bridge)
    for root in roots:  # each project's: the owner's Atlassian sign-in (J3, the machine's or one left in a project's
        # own: it acts in Jira as the owner), and the keys of the owner's own MCP servers (E2)
        for project in [root] + sorted((root / PROJECTS_DIR).glob("*")):
            if not (project / "config.json").exists():
                continue
            try:
                auth = load_config(project).get("jira_oauth")
            except SystemExit:
                auth = None
            for key in ("access", "refresh"):
                value = str(auth.get(key) or "").encode("utf-8") if isinstance(auth, dict) else b""
                if len(value) >= 20:
                    found.add(value)
            found |= mcp_secret_values(project)
    for root in roots:  # a project's Google Chat (G1, G4): its sign-in, its client's secret, its webhooks' addresses
        try:
            config = load_config(root)
        except SystemExit:
            continue
        values = [(config.get("gchat_oauth") or {}).get(k) for k in ("access", "refresh")] if isinstance(
            config.get("gchat_oauth"), dict) else []
        if isinstance(config.get("gchat_client"), dict):
            values.append(config["gchat_client"].get("secret"))
        if isinstance(config.get("gchat_hooks"), dict):
            for hook in config["gchat_hooks"].values():
                query = urllib.parse.parse_qs(urllib.parse.urlsplit(str(hook)).query)
                values += [str(hook)] + query.get("key", []) + query.get("token", [])
        for value in values:
            value = str(value or "").encode("utf-8")
            if len(value) >= 20:
                found.add(value)
    return found


def inside_any(path, folders):
    """Is path one of these folders or inside one? By file identity, so case and aliases do not matter."""
    marks = []
    for folder in folders:
        try:
            marks.append((os.path.normcase(str(Path(folder).resolve())), os.stat(folder)))
        except OSError:
            pass
    for part in (path, *path.parents):
        try:
            here = os.stat(part)
        except OSError:
            continue
        for name, mark in marks:
            if here.st_ino and mark.st_ino:  # file ids: the same folder whatever its name
                if os.path.samestat(here, mark):
                    return True
            elif os.path.normcase(str(part)) == name:  # some network drives on Windows report none
                return True
    return False


REMOTE_FOLDER_FILES = ("files can only be shared from folders on the chat's own machine; this folder is "
                       "connected from another machine.")


# Screenshots saved outside the project, which an agent shares as they are: copying or moving one into the project
# took a Bash command, and one more approval, for every screenshot (11 Nov two-machine test). Claude in Chrome's
# (save_to_disk), in a folder of its own made in the temporary folder of Claude Code's process, and the mobile bridge's
# (mobile_save_screenshot outside the project, screenshot_path), in one the device proxy makes: each private to the user
# (mode 700). Known by name and owner, not place: crewchat's own process may have another temporary folder (a service
# on macOS has no TMPDIR).
CHROME_SHOTS = "claude-chrome-screenshots-"
CREWCHAT_SHOTS = "crewchat-screenshots-"
SHOT_TYPES = {".png", ".jpg", ".jpeg", ".webp", ".gif"}


def saved_screenshot(path):
    """Is this resolved path an image right in one of those screenshot folders, a folder this user owns and nobody else
    can open?"""
    folder = path.parent
    if path.suffix.lower() not in SHOT_TYPES or not folder.name.startswith((CHROME_SHOTS, CREWCHAT_SHOTS)):
        return False
    try:
        info = folder.stat()
    except OSError:
        return False
    if not stat.S_ISDIR(info.st_mode) or not path.is_file():
        return False
    if hasattr(os, "getuid") and (info.st_uid != os.getuid() or info.st_mode & 0o077):
        return False  # another user's, or one others can open or write into
    return True


def share_file(hub, path, folders):
    """Share a file from this machine (hub_send files). folders: the agent's own folders, the only
    ones it may share from; None for the owner, who may share any file."""
    if not isinstance(path, str) or not os.path.isabs(os.path.expanduser(path)):
        raise HubError("files must be absolute paths on this machine")
    # An agent can be talked into sharing crewchat's keys, which agents on linked machines could then
    # open: nothing from crewchat's own folders, and nothing that holds one of its tokens (.mcp.json).
    # Resolved once and read from there, so a symlink cannot point elsewhere after the check. Folders
    # are compared by identity, not by name: a path in another case (macOS, Windows) is the same folder.
    name = Path(path).name
    path = Path(path).expanduser().resolve()
    homes = crewchat_homes(hub)
    if inside_any(path, homes):
        raise HubError("%s is in crewchat's own folder, which holds its keys, so it cannot be shared" % name)
    # Nothing from elsewhere on the machine either (~/.ssh, ~/.aws, another project's .env): what an
    # agent shares must be in its project, where copying it in is the agent's own visible step.
    secret = [Path.home() / d for d in SECRET_DIRS]
    if folders is not None and (inside_any(path, secret) or path.name in SECRET_FILES):
        raise HubError("%s holds credentials (keys, cloud logins), so an agent cannot share it" % name)
    if folders is not None and not inside_any(path, folders) and not saved_screenshot(path):
        raise HubError("%s is outside your project folder (%s), so it cannot be shared. Copy it into the project "
                       "first if the owner should see it. A browser or device screenshot can be shared from where it was saved."
                       % (name, ", ".join(str(f) for f in folders) or "none here"))
    try:
        if path.stat().st_size > MAX_UPLOAD:
            raise HubError("%s is too big: %s at most" % (name, human_size(MAX_UPLOAD)))
        data = path.read_bytes()
    except OSError as e:
        raise HubError("cannot read %s (%s)" % (path, e.strerror or e))
    if any(token in data for token in stored_tokens(homes)):
        raise HubError("%s contains a crewchat token, so it cannot be shared" % name)
    return hub.add_file(name, data)


def file_for(hub, fid):
    """The agent a shared file is for (A2), or None for a file for all: from the file's own meta.json when it is kept
    here, else from its entry in the messages that carry it. One mark on any of them holds."""
    meta, _ = hub.file(fid)
    if meta is not None and meta.get("for") not in (None, ""):
        return meta["for"]
    with hub.lock:
        for m in hub.messages:
            for f in m.get("files") or []:
                if f.get("id") == fid and f.get("for") not in (None, ""):
                    return f["for"]
    return None


def open_shared_file(hub, fid, viewer):
    """hub_file, for `viewer`: an image to look at, a text file's contents, or else where the file is."""
    fid = str(fid or "").strip().lower()
    if not FILE_ID_RE.match(fid):
        raise HubError("id must be the file id a message shows, like [file 1a2b3c4d5e6f7a8b: ...]")
    meant = file_for(hub, fid)
    if meant is not None and viewer not in (meant, OWNER):
        raise HubError(FOR_THE_ADVISOR)
    meta, path = hub.open_file(fid)
    if meta is None:
        raise HubError("no shared file with id %s" % fid)
    head = "%s (%s, %s), saved at %s" % (meta["name"], meta["type"], human_size(meta["size"]), path)
    if meta["type"] in INLINE_IMAGES and meta["size"] <= MAX_TOOL_IMAGE:
        import base64
        return [{"type": "text", "text": head},
                {"type": "image", "data": base64.b64encode(path.read_bytes()).decode("ascii"), "mimeType": meta["type"]}]
    if is_text(meta["type"]) and meta["size"] <= MAX_TOOL_TEXT:
        return "%s:\n\n%s" % (head, path.read_text(encoding="utf-8", errors="replace"))
    return head + ". Open it from that path with your own tools."


def handle_rpc(hub, sid, req, owner=False):
    """One JSON-RPC message in, a response dict out (None for notifications)."""
    if not isinstance(req, dict) or req.get("jsonrpc") != "2.0":
        return {"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}}
    if "method" not in req:
        return None  # a response from the client; nothing to do
    rid, method, params = req.get("id"), req["method"], req.get("params") or {}
    if "id" not in req:
        return None  # notification

    def ok(result):
        return {"jsonrpc": "2.0", "id": rid, "result": result}

    def err(code, message):
        return {"jsonrpc": "2.0", "id": rid, "error": {"code": code, "message": message}}

    if method == "initialize":
        wanted = params.get("protocolVersion") if isinstance(params, dict) else None
        return ok(
            {
                "protocolVersion": wanted if wanted in PROTOCOLS else PROTOCOLS[0],
                "capabilities": {"tools": {"listChanged": True}},  # a lead's or an advisor's list grows (C5, C7)
                "serverInfo": {"name": SERVER_NAME, "version": __version__},
                "instructions": PROTOCOL.format(project=hub.roster.project, trust=TRUST_NOTE),
            }
        )
    if method == "ping":
        return ok({})
    if method == "tools/list":
        return ok({"tools": tools_for(hub, sid, owner)})
    if method == "tools/call":
        if not isinstance(params, dict) or not isinstance(params.get("name"), str):
            return err(-32602, "Invalid params")
        try:
            out = call_tool(hub, sid, params["name"], params.get("arguments") or {}, owner)
            content = out if isinstance(out, list) else [{"type": "text", "text": out}]
            return ok({"content": content, "isError": False})
        except HubError as e:
            return ok({"content": [{"type": "text", "text": "Error: %s" % e}], "isError": True})
    return err(-32601, "Method not found: %s" % method)


# --------------------------------------------------------------------------------------------
# HTTP
# --------------------------------------------------------------------------------------------
PAGE_HEADERS = {
    "Content-Security-Policy": "default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; "
    "connect-src 'self'; img-src 'self' data: blob:; manifest-src 'self'; worker-src 'self'; base-uri 'none'; "
    "form-action 'self'; frame-ancestors 'none'",
    "X-Content-Type-Options": "nosniff",
    "X-Frame-Options": "DENY",  # frame-ancestors, for browsers too old to know it
    # same-origin, not no-referrer: with no-referrer browsers send "Origin: null" on the sign-in
    # form's POST, which the same-origin check below would refuse.
    "Referrer-Policy": "same-origin",
    "Cache-Control": "no-store",
}
# --------------------------------------------------------------------------------------------
# The chat page's Commands tab: every command, for help, and the safe ones to run from the page
# --------------------------------------------------------------------------------------------
# (usage, what it does, how the page runs it or None). A run is the argv to pass, "{NAME}" for a
# value the owner types, "chat" for commands that act on the project the page shows, and "ask"
# for ones that change something, so the page asks first. Commands that remove, unlink, stop or
# uninstall are never run from the page: a stray tap on a phone must not undo a setup.
