RUNNABLE = {usage: run for _group, rows in COMMANDS for usage, _text, run in rows if run}
RUN_VALUE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9 ._:@-]{0,63}$")  # a typed value: no options, no paths
RUN_TIMEOUT = 60
RUN_SLOTS = threading.BoundedSemaphore(2)  # commands run from the page at once (a double tap, two tabs)
ANSI = re.compile(r"\x1b\[[0-9;]*[A-Za-z]")


def commands_catalog():
    """The Commands tab: groups of {usage, text, run, needs, ask}."""
    return [{"group": group, "commands": [
        {"usage": usage, "text": text, "run": bool(run), "ask": bool(run and run.get("ask")),
         "needs": [part[1:-1] for part in (run or {}).get("argv", []) if part.startswith("{")]}
        for usage, text, run in rows]} for group, rows in COMMANDS]


def run_listed_command(usage, values=None, chat=""):
    """Run one of the page's runnable commands as `crewchat ...` and return {code, output}. Only the
    listed commands, with typed values checked; a separate process, so a slow or failing command
    cannot hold up the server."""
    spec = RUNNABLE.get(usage)
    if spec is None:
        raise HubError("that command cannot be run from the page; copy it into a terminal")
    values = values if isinstance(values, dict) else {}
    argv = []
    for part in spec["argv"]:
        if part.startswith("{"):
            name = part[1:-1]
            value = str(values.get(name) or "").strip()
            if not RUN_VALUE.match(value):
                raise HubError("type the %s first (letters, digits, spaces, . _ : @ -)" % name.lower())
            argv.append(value)
        else:
            argv.append(part)
    if spec.get("chat") and chat:
        argv += ["--chat", chat]
    return run_crewchat(argv)


def run_crewchat(argv, root=None):
    """`crewchat ...` in a separate process, for the page; returns {code, output}. root: the machine's
    crewchat folder (CREWCHAT_HOME) when it is not the default."""
    env = dict(os.environ, NO_COLOR="1", CREWCHAT_NO_UPDATE_CHECK="1", CREWCHAT_FROM_SERVER="1")
    if root is not None:
        env["CREWCHAT_HOME"] = str(root)
    flags = CREATE_NO_WINDOW if os.name == "nt" else 0  # no console flashing up on Windows
    if not RUN_SLOTS.acquire(blocking=False):
        raise HubError("two commands are still running; wait for one to finish")
    try:
        done = subprocess.run([sys.executable, os.path.abspath(__file__)] + argv, stdin=subprocess.DEVNULL,
                              capture_output=True, text=True, timeout=RUN_TIMEOUT, env=env,
                              cwd=str(root or home()), creationflags=flags, encoding="utf-8", errors="replace")
    except subprocess.TimeoutExpired:
        return {"code": -1, "output": "Still running after %d seconds, so it was stopped." % RUN_TIMEOUT}
    except OSError as e:
        raise HubError("could not run it: %s" % e)
    finally:
        RUN_SLOTS.release()
    text = done.stdout.rstrip()
    if done.stderr.strip():
        text = (text + "\n" if text else "") + done.stderr.rstrip()
    return {"code": done.returncode, "output": ANSI.sub("", text)[:20000] or "(no output)"}


MAX_LISTED_FOLDERS = 500  # Browse on the page lists this many folders of one folder


def typed_folder(path):
    """A folder path the owner typed on the page, made absolute (~ is the home folder)."""
    raw = str(path or "").strip()
    if not raw:
        raise HubError("type the folder's path")
    folder = Path(os.path.expanduser(raw))
    if not folder.is_absolute():
        raise HubError("type the folder's full path, such as ~/code/my-app")
    return folder.resolve()


def list_folders(path, root=None):
    """The folders in a folder on this machine, for New agent's Browse: hidden ones (.git, .cache)
    and crewchat's own folder left out. A path that is not there yet lists the nearest folder above
    it that is (missing: the path asked for)."""
    asked = folder = typed_folder(path or "~")
    while not folder.is_dir() and folder.parent != folder:
        folder = folder.parent
    own = Path(root or home()).resolve()
    try:
        mine = os.stat(str(own))
    except OSError:
        mine = None

    def is_own(entry):
        """crewchat's folder: by its path, or by file identity for another name of it (POSIX only:
        on Windows, scandir's stat leaves st_ino at 0)."""
        if os.path.normcase(entry.path) == os.path.normcase(str(own)):
            return True
        st = entry.stat()
        return bool(mine and st.st_ino) and os.path.samestat(st, mine)
    try:
        names = sorted((e.name for e in os.scandir(folder) if not e.name.startswith(".") and e.is_dir()
                        and not is_own(e)), key=str.lower)
    except OSError as e:  # no permission (on a Mac: Desktop, Documents)
        raise HubError("cannot open %s (%s)" % (folder, e.strerror or e))
    return {"path": str(folder), "parent": str(folder.parent) if folder.parent != folder else "",
            "home": str(Path.home().resolve()), "more": len(names) > MAX_LISTED_FOLDERS,
            "missing": str(asked) if asked != folder else "",
            "folders": [{"name": n, "path": str(folder / n)} for n in names[:MAX_LISTED_FOLDERS]]}


def make_folder(path, name, root=None):
    """A new folder called name in a folder on this machine, made from New agent's Browse."""
    parent = typed_folder(path)
    name = str(name or "").strip()
    # Not hidden (Browse would not show it), and nothing Windows refuses or quietly changes.
    if (not name or name.startswith(".") or name.endswith((".", " ")) or len(name) > 100
            or re.search(r'[\\/:*?"<>|\x00-\x1f]', name)):
        raise HubError('a folder\'s name has no / \\ : * ? " < > |, does not start or end with a dot, '
                       'and is 100 characters at most')
    folder = parent / name
    if inside_any(folder, {Path(root or home())}):
        raise HubError("not in crewchat's own folder")
    try:
        folder.mkdir()
    except FileExistsError:
        raise HubError("there is already a %s in %s" % (name, parent))
    except OSError as e:  # no such parent, no permission
        raise HubError("could not make %s (%s)" % (folder, e.strerror or e))
    return str(folder)


def connect_folder(path, chat, root=None, create=False, tools=None):
    """The owner connects a folder on this machine to a project from the chat page's New agent:
    `crewchat start` in it, as in a terminal (create: make the folder first if it is not there), for the tools
    picked (W11; None: every tool found here). Returns the folder as the launch options list it."""
    folder = typed_folder(path)
    # Not the disk, home or above it (a .claude folder there is every session's), nor crewchat's own folder.
    if folder == Path(folder.anchor) or inside_any(Path.home(), {folder}) or inside_any(folder, {Path(root or home())}):
        raise HubError("pick a project's own folder, not %s" % folder)
    if not folder.is_dir():
        if not create:
            raise HubError("there is no folder at %s" % folder)
        make_folder(folder.parent, folder.name, root)
    for client in tools or ["all"]:  # the first connects it; each next one adds its tool
        done = run_crewchat(["start", str(folder), "--chat", chat, "--no-open", "--client", client], root)
        if done["code"] != 0:
            lines = [line for line in done["output"].splitlines() if line.strip()]
            raise HubError(re.sub(r"^(- |crewchat: )", "", lines[-1]) if lines else "crewchat start failed")
    return str(folder)


def phone_link(projects, chat, setup=False):
    """The phone panel: the address a phone on the owner's tailnet opens, and a sign-in link to it with a fresh
    single-use code, as text and as a QR code to scan. setup: give the chat a tailnet address first (`tailscale
    serve`, as `crewchat peers invite` does) when it has none. No address: why, for the panel to say."""
    primary = projects.primary
    root = primary.roster.root
    config = load_config(root)
    port = int(config["port"])
    url = str(config.get("url") or "").rstrip("/")
    if url.startswith(("http://127.0.0.1", "http://localhost")):
        url = ""
    why = ""
    if not url:
        try:
            import crewchat_peers
        except ImportError:
            crewchat_peers = None
        exe = find_tailscale()
        if crewchat_peers is None or not exe:
            why = "Tailscale is not installed on this machine (https://tailscale.com/download)"
        elif setup:
            url, why = crewchat_peers.tailscale_address(port)
            url = (url or "").rstrip("/")
            if url:
                change_config(lambda saved: saved.update(url=url), root)
        else:
            url = crewchat_peers.served_url(crewchat_peers._tailscale_json(exe, "serve", "status"), port).rstrip("/")
            why = "" if url else "the chat has no address on your tailnet yet"
    if not url:
        return {"url": "", "why": why or "the chat has no address on your tailnet yet",
                "can_setup": crewchat_peers is not None and bool(exe)}
    code = primary.hub.new_code()
    link = url + "/login?" + urllib.parse.urlencode([("code", code)] + ([("chat", chat)] if chat else []))
    return {"url": url, "link": link, "code": "%s-%s" % (code[:4], code[4:]), "ttl": CODE_TTL, "qr": qr_matrix(link)}


def answer_need(hub, data):
    """The owner's answer to an item in Needs you, by its key (R8): Allow or Deny for a permission prompt or a
    browser call, Approve or Decline for a process note, a reply to a blocked task or a review, or Done for a
    review. By the key's kind, not by what still waits, so an item that is gone says so. Also a phone's signed answer
    from the hosted page (W13, crewchat_cloud), checked there."""
    key, answer = data.get("key"), data.get("answer")
    kind, _, ref = key.partition(":") if isinstance(key, str) else ("", "", "")
    if not ref or kind not in NEED_KINDS:
        raise HubError("bad key")
    own, at, device = ref.rpartition("@")
    if at and kind in SHARED_NEED_KINDS and own:
        with hub.lock:
            theirs = device in hub.remote_needs
        if theirs:  # a linked machine's own item: the answer goes to that machine, which checks it (peer_need)
            return hub.answer_remote_need(device, "%s:%s" % (kind, own), data)
    if kind == "permission":
        return hub.answer_permission(ref, answer, data.get("note"))
    if kind == "question":  # an agent's multiple-choice questions: the owner's answer to each
        return hub.answer_question(ref, answer, data.get("answers"))
    if kind == "browser":
        return hub.answer_browser(ref, answer)
    if kind == "device":
        return hub.answer_device(ref, answer)
    if kind == "gchat":
        return hub.gchat_answer(ref, answer)
    if kind == "jira_flow":  # a pull request to review, fixes to look at, or a stuck ticket (F5, F6)
        return hub.flow_answer(ref, answer, data.get("text") or data.get("note") or "")
    if kind == "firstrun":
        return hub.answer_first_run(ref, answer)
    if kind == "stuck":
        return hub.answer_stuck(ref, answer)
    if kind == "start_failed":
        return hub.answer_start_failed(ref, answer)
    if kind == "ended":  # a background session Claude Code ended while it was idle: Reopen, or leave it
        return hub.answer_ended(ref, answer)
    if kind == "ask":
        return hub.answer_ask(ref, answer, data.get("text"))
    if kind == "message":  # an agent's question to the owner: answered in the chat, or set aside here
        if answer != "dismiss":
            raise HubError("answer it in the chat, or dismiss it")
        return hub.dismiss_question(ref)
    if kind == "lease":  # a commit a lease stopped (W8)
        return hub.answer_lease(ref, answer)
    if kind == "process":
        if answer == "approve":
            return {"said": hub.approve_process(OWNER, ref, data.get("of") or "")}
        if answer == "decline":
            hub.decline_process(OWNER, ref, data.get("of") or "")
            return {"ok": True}
        raise HubError("answer is approve or decline")
    if kind not in ("blocked", "review", "parked"):
        raise HubError("nothing to answer for %s" % kind)
    item = next((n for n in hub.needs_you() if n["key"] == key), None)
    if item is None:
        raise HubError("that is not waiting any more")
    if answer == "done" and kind == "review":
        hub.owner_status(ref, "done")
        return {"ok": True}
    text = str(data.get("text") or "").strip()
    if answer != "reply" or not text:
        raise HubError("answer is a reply with its text" + (", or done" if kind == "review" else ""))
    # With its Re # as well as `re`, so a linked machine still on 1.1 (which drops `re`) sees the answer too.
    return {"id": hub.send(OWNER, hub.reply_to_task(ref, item["agent"] or item["holder"]), "Re #%s: %s" % (ref, text),
                           re=ref)["id"]}


